insert into public.paths (id, sort, title, subtitle, status) values
  ($uxg$P01$uxg$, 0, $uxg${"en":"Forms That Flow","ar":"نماذج تسير بسلاسة"}$uxg$::jsonb, $uxg${"en":"Design forms people can finish, understand and recover from, in English and Arabic.","ar":"صمّم نماذج يستطيع الناس إكمالها وفهمها والتعافي من أخطائها، بالعربية والإنجليزية."}$uxg$::jsonb, $uxg$published$uxg$)
insert into public.units (id, path_id, sort, title, free) values
  ($uxg$P01-U01$uxg$, $uxg$P01$uxg$, 0, $uxg${"en":"Ask only what you need","ar":"اسأل فقط عمّا تحتاجه"}$uxg$::jsonb, true),
  ($uxg$P01-U02$uxg$, $uxg$P01$uxg$, 1, $uxg${"en":"Pick the right control","ar":"اختر عنصر التحكّم المناسب"}$uxg$::jsonb, false)
insert into public.skills (id, unit_id, title, criterion) values
  ($uxg$SK-P01-U01-01$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Cut the fields the form doesn't need","ar":"احذف الحقول التي لا يحتاجها النموذج"}$uxg$::jsonb, $uxg${"en":"Remove fields nobody uses, while keeping every field the task really needs.","ar":"احذف الحقول التي لا يستخدمها أحد، مع الإبقاء على كل حقل تحتاجه المهمّة فعلًا."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-02$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Postpone what can wait","ar":"أجّل ما يمكن أن ينتظر"}$uxg$::jsonb, $uxg${"en":"Move questions that are needed only later to the step where they're needed.","ar":"انقل الأسئلة التي تُحتاج لاحقًا فقط إلى الخطوة التي تُحتاج فيها."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-03$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Explain why you ask for personal details","ar":"اشرح لماذا تطلب البيانات الشخصية"}$uxg$::jsonb, $uxg${"en":"Say at the field who sees a personal detail and what it's used for.","ar":"قل عند الحقل مَن يرى المعلومة الشخصية وفيمَ تُستخدم."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-04$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Mark required and optional fields","ar":"وضّح الحقول المطلوبة والاختيارية"}$uxg$::jsonb, $uxg${"en":"Put a star on every required field and label the few optional ones, at the field.","ar":"ضع نجمة على كل حقل مطلوب واكتب «اختياري» على الحقول الاختيارية القليلة، عند الحقل نفسه."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-05$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Keep the check true to the label","ar":"اجعل التحقّق مطابقًا للعنوان"}$uxg$::jsonb, $uxg${"en":"Make sure a field labelled optional is never blocked when left empty.","ar":"تأكّد أن الحقل المكتوب عليه «اختياري» لا يُمنع أبدًا إذا تُرك فارغًا."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-06$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Ask for a name in one field","ar":"اطلب الاسم في حقل واحد"}$uxg$::jsonb, $uxg${"en":"Use one full-name field that fits every naming pattern.","ar":"استخدم حقلًا واحدًا للاسم الكامل يناسب كل أنماط الأسماء."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-07$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Accept numbers the way people write them","ar":"اقبل الأرقام كما يكتبها الناس"}$uxg$::jsonb, $uxg${"en":"Accept spaces, dashes and country codes in phone numbers, and tidy them for people.","ar":"اقبل المسافات والشَرطات ومفاتيح الدول في أرقام الهواتف، ونظّمها بدلًا من الناس."}$uxg$::jsonb),
  ($uxg$SK-P01-U01-08$uxg$, $uxg$P01-U01$uxg$, $uxg${"en":"Use labels and formats people understand","ar":"استخدم عناوين وصيغًا يفهمها الناس"}$uxg$::jsonb, $uxg${"en":"Replace internal terms with plain words, and spell out months in dates.","ar":"استبدل المصطلحات الداخلية بكلمات بسيطة، واكتب أسماء الشهور في التواريخ."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-01$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Use a toggle only for instant settings","ar":"استخدم الـ Toggle للإعدادات الفورية فقط"}$uxg$::jsonb, $uxg${"en":"Use a toggle when the change happens at once, and a checkbox when it waits for a button.","ar":"استخدم الـ Toggle عندما يحدث التغيير فورًا، والـ Checkbox عندما ينتظر الضغط على زر."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-02$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"One answer or several, shown not hidden","ar":"إجابة واحدة أم عدة، معروضة لا مخفية"}$uxg$::jsonb, $uxg${"en":"Use radio buttons for one of a few, checkboxes for any number, and skip the dropdown for short lists.","ar":"استخدم الـ Radio buttons لإجابة واحدة من خيارات قليلة، والـ Checkboxes لأي عدد، وتجنّب القائمة المنسدلة للقوائم القصيرة."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-03$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Choose defaults with care","ar":"اختر القيم الافتراضية بعناية"}$uxg$::jsonb, $uxg${"en":"Preselect a safe, common choice, and never preselect a guess about someone personally.","ar":"اختر مسبقًا خيارًا آمنًا وشائعًا، ولا تختر مسبقًا أبدًا تخمينًا عن شخص بعينه."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-04$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Let people type what they know","ar":"دع الناس يكتبون ما يعرفونه"}$uxg$::jsonb, $uxg${"en":"Use a typed field for values people know by heart, like a year or a date far away.","ar":"استخدم حقلًا للكتابة للقيم التي يحفظها الناس، مثل سنة أو تاريخ بعيد."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-05$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Show only the choices that are available","ar":"اعرض الخيارات المتاحة فقط"}$uxg$::jsonb, $uxg${"en":"Grey out dates and times that can't be booked, instead of rejecting them afterwards.","ar":"اجعل التواريخ والأوقات غير المتاحة باهتة، بدل رفضها بعد اختيارها."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-06$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Pick the right control for numbers","ar":"اختر العنصر المناسب للأرقام"}$uxg$::jsonb, $uxg${"en":"Use a stepper for small counts with a usual value, typing for large or exact numbers, and a text box beside any slider.","ar":"استخدم الـ Stepper للأعداد الصغيرة ذات القيمة المعتادة، والكتابة للأرقام الكبيرة أو الدقيقة، ومربع نص بجانب أي Slider."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-07$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Treat codes as text made of digits","ar":"تعامل مع الرموز كنص من أرقام"}$uxg$::jsonb, $uxg${"en":"Give IDs and codes a text field with the number pad, so leading zeros and length stay intact.","ar":"أعطِ الأرقام التعريفية والرموز حقلًا نصيًا بلوحة أرقام، حتى تبقى الأصفار الأولى والطول كما هي."}$uxg$::jsonb),
  ($uxg$SK-P01-U02-08$uxg$, $uxg$P01-U02$uxg$, $uxg${"en":"Make long lists searchable and forgiving","ar":"اجعل القوائم الطويلة قابلة للبحث ومتسامحة"}$uxg$::jsonb, $uxg${"en":"Let people type to narrow long lists, suggest matches for typos, and pin common options without preselecting them.","ar":"دع الناس يكتبون لتضييق القوائم الطويلة، واقترح نتائج للأخطاء الإملائية، وثبّت الخيارات الشائعة في الأعلى دون اختيارها مسبقًا."}$uxg$::jsonb)
insert into public.lessons (id, unit_id, sort, mode, minutes) values
  ($uxg$P01-U01-L01$uxg$, $uxg$P01-U01$uxg$, 0, $uxg$lesson$uxg$, 8),
  ($uxg$P01-U01-L02$uxg$, $uxg$P01-U01$uxg$, 1, $uxg$lesson$uxg$, 8),
  ($uxg$P01-U01-L03$uxg$, $uxg$P01-U01$uxg$, 2, $uxg$lesson$uxg$, 8),
  ($uxg$P01-U01-L04$uxg$, $uxg$P01-U01$uxg$, 3, $uxg$check$uxg$, 7),
  ($uxg$P01-U02-L01$uxg$, $uxg$P01-U02$uxg$, 0, $uxg$lesson$uxg$, 8),
  ($uxg$P01-U02-L02$uxg$, $uxg$P01-U02$uxg$, 1, $uxg$lesson$uxg$, 8),
  ($uxg$P01-U02-L03$uxg$, $uxg$P01-U02$uxg$, 2, $uxg$lesson$uxg$, 8),
  ($uxg$P01-U02-L04$uxg$, $uxg$P01-U02$uxg$, 3, $uxg$check$uxg$, 7)
insert into public.content_versions (lesson_id, hash, body) values
  ($uxg$P01-U01-L01$uxg$, $uxg$5d14ca8b03c43e4a6931dfd5834f60784e3b932965c1fa43767bc3247cab50f3$uxg$, $uxg${"id":"P01-U01-L01","mode":"lesson","minutes":8,"title":{"en":"Every field costs something","ar":"لكل حقل ثمن"},"speaker":"hana","review_labels":{"MC-P01-001":{"en":"Ask for what the task needs now","ar":"اسأل عمّا تحتاجه المهمة الآن"},"MC-P01-002":{"en":"\"Might be useful later\" isn't a reason to ask","ar":"«قد يفيد لاحقًا» ليس سببًا للسؤال"},"MC-P01-005":{"en":"Many optional fields mean too many fields","ar":"كثرة الحقول الاختيارية تعني كثرة الحقول"},"MC-P01-026":{"en":"Shortest isn't the goal; essential is","ar":"الهدف ليس الأقصر؛ بل الضروري"},"MC-P01-027":{"en":"Say why you ask for personal details","ar":"وضّح لماذا تطلب المعلومات الشخصية"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Salma wants to try our gym","ar":"سلمى تريد تجربة نادينا"},"body":{"en":"Salma saw our offer of a free 3-day trial; my gym is near her work. She tapped \"Try it free\" on her phone during her lunch break.\n\nThis is the form she got.","ar":"رأت سلمى عرضنا لتجربة مجانية لمدة 3 أيام، فناديّ قريب من عملها. وضغطت «جرّبه مجانًا» على هاتفها في استراحة الغداء.\n\nوهذا هو النموذج الذي ظهر لها."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-01","part":"try","rules":["R12"],"value":{"en":"Try first. EAS framework (NN/g): asking for unnecessary information adds effort and can make people question your intentions. A national ID for a free trial is the clearest case.","ar":"جرّب أولًا. إطار EAS (NN/g): طلب معلومات غير ضرورية يزيد الجهد وقد يجعل الناس يشكّون في نواياك. والرقم القومي لتجربة مجانية أوضح مثال."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Asking for unnecessary information increases user effort and can cause users to question your intentions."},"prompt":{"en":"The gym can remove one field today. Try each one. Which should go first?","ar":"يستطيع النادي حذف حقل واحد اليوم. جرّب كل واحد. أيّها يجب أن يُحذف أولًا؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]},"options":[{"id":"phone","text":{"en":"Remove the mobile number","ar":"احذف رقم الموبايل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"nid","text":{"en":"Remove the national ID number","ar":"احذف الرقم القومي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"name","text":{"en":"Remove the full name","ar":"احذف الاسم الكامل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}}],"answer":["nid"],"misconceptions":[{"id":"MC-P01-001","when":["phone","name"],"feedback":{"en":"The front desk needs to know who Salma is and how to reach her, so those fields earn their place. A national ID for a free 3-day trial is personal, and nothing explains why it's needed.","ar":"يحتاج الاستقبال أن يعرف من هي سلمى وكيف يتواصل معها، فهذان الحقلان لهما مكانهما. أما الرقم القومي لتجربة مجانية لثلاثة أيام فهو شخصي، ولا شيء يوضّح لماذا يُطلب."}}],"hints":[{"en":"Look at what the trial needs: Salma comes in, the gym greets her and can reach her.","ar":"انظر إلى ما تحتاجه التجربة: تأتي سلمى، فيرحّب بها الجيم ويستطيع التواصل معها."},{"en":"Which field does the trial never use, and is also the most personal?","ar":"أي حقل لا تستخدمه التجربة أبدًا، وهو أيضًا الأكثر خصوصية؟"}],"correct":{"en":"The national ID: personal, and the trial doesn't need it.","ar":"الرقم القومي: شخصي، والتجربة لا تحتاجه."},"explain":{"en":"Every field costs time. A personal question the task doesn't explain also costs trust, and people start to wonder what the data is really for.","ar":"كل حقل يكلّف وقتًا. والسؤال الشخصي الذي لا تبرّره المهمة يكلّف ثقة أيضًا، فيبدأ الناس في التساؤل عن الغرض الحقيقي من البيانات."}},{"id":"S03","type":"card","part":"concept","icons":["target","clock","none","idea"],"title":{"en":"A field is a question you make someone answer","ar":"الحقل سؤال تُلزم شخصًا بالإجابة عنه"},"body":{"en":"Each field costs the person time, effort and a little trust. Forms that feel quick get finished. For every field, ask:\n\n- **Is it essential?** If the task can't happen without it, keep it.\n- **Is it needed now?** If it can wait until later, ask later.\n- **Will anyone use it?** If there's no clear use for the answer, don't ask.\n- **Is it personal?** Then say why you're asking and how you'll use it.","ar":"كل حقل يكلّف الشخص وقتًا وجهدًا وقليلًا من الثقة. والنماذج التي تبدو سريعة تُكمَل. لكل حقل، اسأل:\n\n- **هل هو ضروري؟** إذا كانت المهمة لا تتم بدونه، فأبقِه.\n- **هل نحتاجه الآن؟** إذا كان يمكن أن ينتظر، فاسأل عنه لاحقًا.\n- **هل سيستخدمه أحد؟** إذا لم يكن للإجابة استخدام واضح، فلا تسأل.\n- **هل هو شخصي؟** فوضّح لماذا تسأل وكيف ستستخدمه."}},{"id":"S04","type":"tune","skill":"SK-P01-U01-02","part":"guided","rules":["R06","R15"],"value":{"en":"EAS framework (NN/g): not every question needs to be asked immediately. If it can wait, postpone it. Making questions optional still leaves them on the form.","ar":"إطار EAS (NN/g): ليس كل سؤال يجب أن يُطرح فورًا. إذا كان يمكن أن ينتظر، فأجّله. وجعل الأسئلة اختيارية يُبقيها في النموذج رغم ذلك."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"If it can wait, postpone it."},"scenario":{"en":"We do need Salma's national ID and date of birth, but only if she joins as a member after the trial.","ar":"نحتاج فعلًا الرقم القومي لسلمى وتاريخ ميلادها، لكن فقط إذا اشتركت كعضوة بعد التجربة."},"prompt":{"en":"Try each version of the trial form. Which one should ship?","ar":"جرّب كل نسخة من نموذج التجربة. أيّها يجب أن تُطلق؟"},"start":"optional","options":[{"id":"later","text":{"en":"Ask for them on the membership form, if she joins","ar":"اسأل عنهما في نموذج الاشتراك، إن اشتركت"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"},{"kind":"small","text":{"en":"Membership form, later: national ID, date of birth","ar":"نموذج الاشتراك، لاحقًا: الرقم القومي، تاريخ الميلاد"},"gap":"l"}]}},{"id":"optional","text":{"en":"Keep them on the trial form, marked optional","ar":"أبقِهما في نموذج التجربة، مع وسمهما بأنهما اختياريان"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth (optional)","ar":"تاريخ الميلاد (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number (optional)","ar":"الرقم القومي (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"now","text":{"en":"Keep them required on the trial form, so it's done once","ar":"أبقِهما إلزاميين في نموذج التجربة، لتنتهي منهما مرة واحدة"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}}],"answer":["later"],"misconceptions":[{"id":"MC-P01-005","when":["optional"],"feedback":{"en":"Optional fields are still there to read and wonder about, and many people fill them in anyway, just in case. If it can wait, move it.","ar":"الحقول الاختيارية ما زالت موجودة للقراءة والتفكير، وكثير من الناس يملؤونها على أي حال، احتياطًا. إذا كان يمكن أن ينتظر، فانقله."}},{"id":"MC-P01-001","when":["now"],"feedback":{"en":"Most trial visitors never become members, so they'd all give a national ID for nothing. Ask the people who join, when they join.","ar":"أغلب زوّار التجربة لا يصبحون أعضاء، فسيعطي كلهم رقمهم القومي بلا فائدة. اسأل من يشترك، حين يشترك."}}],"hints":[{"en":"When does the gym actually use the ID and the date of birth?","ar":"متى يستخدم الجيم الرقم القومي وتاريخ الميلاد فعلًا؟"},{"en":"If Salma never joins, will the gym ever need these two?","ar":"إذا لم تنضم سلمى أبدًا، هل سيحتاج الجيم هذين الحقلين؟"}],"correct":{"en":"Ask at the moment it's needed.","ar":"اسأل في اللحظة التي تحتاجه فيها."},"explain":{"en":"Moving a question to the right moment loses nothing. The people who join answer it then, and now they have a reason to.","ar":"نقل السؤال إلى اللحظة المناسبة لا يُضيّع شيئًا. من يشترك سيجيب عنه حينها، ولديه الآن سبب لذلك."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U01-02","part":"guided","rules":["R06","R15"],"value":{"en":"EAS framework (NN/g): start with the bare minimum needed at this stage, then gradually request more. Marketing's question can move after sign-up.","ar":"إطار EAS (NN/g): ابدأ بأقل ما تحتاجه في هذه المرحلة، ثم اطلب المزيد تدريجيًا. وسؤال التسويق يمكن أن ينتقل إلى ما بعد التسجيل."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Start by asking for the bare minimum needed at this stage, then gradually request more, to avoid overwhelming users upfront."},"scenario":{"en":"Our marketing team wants to keep \"How did you hear about us?\" as a required field on the trial form. They do use the answers to plan our ads.","ar":"يريد فريق التسويق عندنا إبقاء «كيف عرفت عنّا؟» حقلًا إلزاميًا في نموذج التجربة. وهم يستخدمون الإجابات فعلًا لتخطيط إعلاناتنا."},"prompt":{"en":"Try each option. Which one should ship?","ar":"جرّب كل خيار. أيّها يجب أن يُطلق؟"},"start":"keep","options":[{"id":"keep","text":{"en":"Keep it required on the form","ar":"أبقِه إلزاميًا في النموذج"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"delete","text":{"en":"Delete it and tell marketing no","ar":"احذفه وارفض طلب التسويق"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"},{"kind":"small","text":{"en":"Marketing gets no answers.","ar":"لا يحصل التسويق على أي إجابات."},"gap":"l"}]}},{"id":"after","text":{"en":"Ask it after she's signed up, as an optional one-tap question","ar":"اسأل عنه بعد أن تسجّل، كسؤال اختياري بضغطة واحدة"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"You're booked! See you tomorrow.","ar":"تمّ حجزك! نراك غدًا."}},{"kind":"meta","text":{"en":"One quick question, if you like: how did you hear about us?","ar":"سؤال سريع، إن أحببت: كيف عرفت عنّا؟"},"gap":"m"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":{"en":"Friend","ar":"صديق"}},{"kind":"chip","text":{"en":"Social media","ar":"مواقع التواصل"}},{"kind":"chip","text":{"en":"Walked past","ar":"مررت بالمكان"}}]}]}}],"answer":["after"],"misconceptions":[{"id":"MC-P01-001","when":["keep"],"feedback":{"en":"The answer helps the gym, not Salma's sign-up. Required, it stands between her and her trial.","ar":"الإجابة تفيد النادي، لا تسجيل سلمى. وإذا كانت إلزامية، فهي تقف بينها وبين تجربتها."}},{"id":"MC-P01-002","when":["delete"],"feedback":{"en":"Marketing really uses the answer, so deleting it loses something. Ask it at a better moment instead.","ar":"التسويق يستخدم الإجابة فعلًا، فحذفها يُضيّع شيئًا. اسأل عنها في لحظة أفضل بدلًا من ذلك."}}],"hints":[{"en":"The answers are useful, but does the trial need them to happen?","ar":"الإجابات مفيدة، لكن هل تحتاجها التجربة لكي تتم؟"},{"en":"Can marketing still get the answer once Salma has signed up?","ar":"هل يمكن أن يحصل التسويق على الإجابة بعد أن تسجّل سلمى؟"}],"correct":{"en":"The minimum first, the extra question after.","ar":"الحد الأدنى أولًا، والسؤال الإضافي بعده."},"explain":{"en":"Salma's sign-up stays short, and marketing still gets answers from people who are happy to tap one.","ar":"يبقى تسجيل سلمى قصيرًا، ويحصل التسويق مع ذلك على إجابات من الناس الذين يسعدهم الضغط على واحدة."},"speaker":"hana"},{"id":"S06","type":"tune","skill":"SK-P01-U01-03","part":"guided","rules":["R06","R15"],"value":{"en":"EAS framework (NN/g): people are more likely to finish a form when they understand how their data will be used. Explain personal fields at the field.","ar":"إطار EAS (NN/g): يزيد احتمال إكمال الناس للنموذج حين يفهمون كيف ستُستخدم بياناتهم. وضّح سبب الحقول الشخصية عند الحقل نفسه."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Users will be more likely to complete the form when they understand how their data will be used."},"scenario":{"en":"Our trial form now asks only for Salma's name and mobile number. She hesitates at the mobile: she doesn't want sales calls.","ar":"نموذج التجربة عندنا يطلب الآن اسم سلمى ورقم موبايلها فقط. لكنها تتردّد عند الموبايل: فهي لا تريد مكالمات بيع."},"prompt":{"en":"Try each version of the mobile field. Which one should ship?","ar":"جرّب كل نسخة من حقل الموبايل. أيّها يجب أن يُطلق؟"},"start":"none","options":[{"id":"none","text":{"en":"Just the label","ar":"التسمية فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""}]}},{"id":"policy","text":{"en":"Add a link to the privacy policy at the bottom","ar":"أضف رابطًا لسياسة الخصوصية في الأسفل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"},{"kind":"link","text":{"en":"Privacy policy","ar":"سياسة الخصوصية"},"gap":"s"}]}},{"id":"why","text":{"en":"Add a line that says what it's for","ar":"أضف سطرًا يوضّح الغرض منه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"We'll text you once to confirm your visit. No marketing.","ar":"سنرسل لك رسالة واحدة لتأكيد زيارتك. بدون رسائل تسويقية."}}]}}],"answer":["why"],"misconceptions":[{"id":"MC-P01-027","when":["none"],"feedback":{"en":"Salma has to guess what the number is for, and her guess is sales calls. Tell her, right at the field.","ar":"على سلمى أن تخمّن الغرض من الرقم، وتخمينها هو مكالمات البيع. أخبرها، عند الحقل مباشرة."}},{"id":"MC-P01-027","when":["policy"],"feedback":{"en":"A policy link is useful, but few people open it at the moment they hesitate. One plain line at the field answers her worry.","ar":"رابط السياسة مفيد، لكن قليلين يفتحونه في لحظة التردّد. وسطر واضح واحد عند الحقل يجيب عن قلقها."}}],"hints":[{"en":"Salma's worry is about this one field. Where is she looking when she hesitates?","ar":"قلق سلمى يخصّ هذا الحقل وحده. أين تنظر عندما تتردّد؟"},{"en":"Will she open a policy page, or read a line next to the field?","ar":"هل ستفتح صفحة السياسة، أم ستقرأ سطرًا بجانب الحقل؟"}],"correct":{"en":"Say why, where the question is.","ar":"وضّح السبب، حيث يوجد السؤال."},"explain":{"en":"A short reason at the field turns a worrying question into a fair one. It also stops you asking for things you can't explain.","ar":"السبب القصير عند الحقل يحوّل السؤال المقلق إلى سؤال عادل. كما يمنعك من طلب أشياء لا تستطيع تبريرها."},"speaker":"hana"},{"id":"S07","type":"compare","skill":"SK-P01-U01-01","part":"contrast","speaker":"tarek","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S02 to S05: cutting is not the goal in itself. EAS (NN/g): forms should ask only for essential information. A form that drops an essential field is short and broken.","ar":"مقارنة مع الخطوات 2 إلى 5: الحذف ليس هدفًا في حدّ ذاته. EAS (NN/g): يجب أن تطلب النماذج المعلومات الضرورية فقط. والنموذج الذي يحذف حقلًا ضروريًا قصير ومعطّل."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Forms should only ask for essential information"},"scenario":{"en":"I manage a lunch delivery app. Tamer is ordering lunch to his office, and my team wants the checkout as short as possible.","ar":"أدير تطبيقًا لتوصيل الغداء. يطلب تامر غداءً إلى مكتبه، ويريد فريقي صفحة الدفع أقصر ما يمكن."},"prompt":{"en":"Which delivery form should ship?","ar":"أي نموذج توصيل يجب أن يُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver (optional)","ar":"ملاحظة للسائق (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},"answer":"b","reason":{"prompt":{"en":"Why is the longer form better here?","ar":"لماذا النموذج الأطول أفضل هنا؟"},"options":[{"id":"more","text":{"en":"More fields look more professional","ar":"الحقول الأكثر تبدو أكثر احترافية"}},{"id":"need","text":{"en":"The driver needs a way to reach Tamer when he arrives","ar":"يحتاج السائق طريقة للوصول إلى تامر حين يصل"}},{"id":"data","text":{"en":"The restaurant gets more data","ar":"يحصل المطعم على بيانات أكثر"}}],"answer":["need"],"misconceptions":[{"id":"MC-P01-026","when":["more","data"],"feedback":{"en":"Neither is a reason to ask. The phone stays because the delivery fails without it.","ar":"لا هذا ولا ذاك سبب للسؤال. يبقى الهاتف لأن التوصيل يفشل بدونه."}}]},"misconceptions":[{"id":"MC-P01-026","when":["a"],"feedback":{"en":"A is shorter, but the driver can't call Tamer from the lobby, and the lunch goes cold. Keep what the task needs.","ar":"A أقصر، لكن السائق لا يستطيع الاتصال بتامر من مدخل المبنى، فيبرد الغداء. أبقِ ما تحتاجه المهمة."}}],"hints":[{"en":"Picture the driver arriving at Tamer's office building. What does he need?","ar":"تخيّل السائق وهو يصل إلى مبنى مكتب تامر. ماذا يحتاج؟"},{"en":"Short is good only until something the delivery needs goes missing.","ar":"القِصر جيد فقط ما لم ينقص شيء يحتاجه التوصيل."}],"correct":{"en":"Essential, not shortest.","ar":"الضروري، لا الأقصر."},"explain":{"en":"Cut what the task doesn't use, and keep what it can't work without. The optional note stays because it's light and helps the driver.","ar":"احذف ما لا تستخدمه المهمة، وأبقِ ما لا تعمل بدونه. والملاحظة الاختيارية تبقى لأنها خفيفة وتساعد السائق."}},{"id":"S08","type":"tune","skill":"SK-P01-U01-01","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Forms usability (NN/g): first, eliminate as many optional fields as possible. A job title has no use in a lunch order, and a birthday belongs where people share extras.","ar":"حالة جديدة. سهولة استخدام النماذج (NN/g): أولًا، احذف أكبر عدد ممكن من الحقول الاختيارية. المسمّى الوظيفي لا فائدة له في طلب غداء، وعيد الميلاد مكانه حيث يشارك الناس الإضافات."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"First, eliminate as many optional fields as possible"},"scenario":{"en":"Our order form also asks Tamer for his job title, and his birthday \"for a gift\". Nothing in the delivery uses either one.","ar":"يسأل نموذج الطلب عندنا تامر أيضًا عن مسمّاه الوظيفي، وعن عيد ميلاده «لهدية». ولا شيء في التوصيل يستخدم أيًّا منهما."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Job title","ar":"المسمّى الوظيفي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your birthday, for a gift","ar":"عيد ميلادك، لهدية"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"optional","text":{"en":"Mark the job title and birthday as optional","ar":"اجعل المسمّى الوظيفي وعيد الميلاد اختياريين"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Job title (optional)","ar":"المسمّى الوظيفي (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your birthday, for a gift (optional)","ar":"عيد ميلادك، لهدية (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"profile","text":{"en":"Remove the job title; offer the birthday in his profile","ar":"احذف المسمّى الوظيفي؛ واعرض عيد الميلاد في ملفه الشخصي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"},{"kind":"small","text":{"en":"Profile, any time: \"Add your birthday and get a gift\"","ar":"الملف الشخصي، في أي وقت: «أضف عيد ميلادك واحصل على هدية»"},"gap":"l"}]}},{"id":"bottom","text":{"en":"Move both below the Place order button","ar":"انقلهما أسفل زر «أكّد الطلب»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"},{"kind":"field","label":{"en":"Job title","ar":"المسمّى الوظيفي"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Your birthday, for a gift","ar":"عيد ميلادك، لهدية"},"text":"","gap":"s"}]}}],"answer":["profile"],"misconceptions":[{"id":"MC-P01-005","when":["optional"],"feedback":{"en":"Now the order has two optional questions nobody needs for lunch. Remove what has no use, and move the extra to where it fits.","ar":"الآن في الطلب سؤالان اختياريان لا يحتاجهما أحد للغداء. احذف ما لا فائدة له، وانقل الإضافة إلى المكان المناسب لها."}},{"id":"MC-P01-002","when":["bottom"],"feedback":{"en":"They're still on the order form, and now in a confusing place: is the order placed or not? Take them off the order.","ar":"ما زالا في نموذج الطلب، والآن في مكان مربك: هل تمّ الطلب أم لا؟ أخرِجهما من الطلب."}}],"hints":[{"en":"Does the delivery use either field? Ask the four questions from the lesson.","ar":"هل يستخدم التوصيل أيًّا من الحقلين؟ اطرح الأسئلة الأربعة من الدرس."},{"en":"An optional field still asks. Is there a place outside the order where the birthday fits?","ar":"الحقل الاختياري ما زال يسأل. هل هناك مكان خارج الطلب يناسب عيد الميلاد؟"}],"correct":{"en":"The order stays about lunch.","ar":"يبقى الطلب عن الغداء."},"explain":{"en":"No use, no field. And an extra that some people want, like a birthday gift, goes where they choose to share it.","ar":"لا فائدة، لا حقل. والإضافة التي يريدها بعض الناس، مثل هدية عيد الميلاد، تذهب حيث يختارون مشاركتها."}},{"id":"S09","type":"card","part":"recap","icons":["target","clock","none","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Essential only:** removed the field the task didn't need.\n- **Ask later:** moved membership questions to the membership form.\n- **Minimum first:** asked marketing's question after sign-up.\n- **Say why:** explained the personal field at the field.\n- **Not just short:** kept the field the delivery can't work without.\n\nNext lesson: required or optional, and how to show it.","ar":"- **الضروري فقط:** حذفت الحقل الذي لا تحتاجه المهمة.\n- **اسأل لاحقًا:** نقلت أسئلة الاشتراك إلى نموذج الاشتراك.\n- **الحد الأدنى أولًا:** طرحت سؤال التسويق بعد التسجيل.\n- **وضّح السبب:** شرحت الحقل الشخصي عند الحقل نفسه.\n- **ليس الأقصر فقط:** أبقيت الحقل الذي لا يعمل التوصيل بدونه.\n\nالدرس التالي: إلزامي أم اختياري، وكيف توضّح ذلك."}}]}$uxg$::jsonb),
  ($uxg$P01-U01-L02$uxg$, $uxg$8d88fe731a22dad285797ae11e9dd0a65ff6a03ab34813c0a60be40abc50fa60$uxg$, $uxg${"id":"P01-U01-L02","mode":"lesson","minutes":8,"title":{"en":"Required or optional? Show it on every field","ar":"إلزامي أم اختياري؟ وضّحه في كل حقل"},"speaker":"hana","review_labels":{"MC-P01-001":{"en":"Ask for what the task needs now","ar":"اسأل عمّا تحتاجه المهمة الآن"},"MC-P01-003":{"en":"A style alone doesn't say what's required","ar":"الشكل وحده لا يوضّح ما هو إلزامي"},"MC-P01-004":{"en":"The label and the check must agree","ar":"يجب أن تتّفق التسمية مع التحقق"},"MC-P01-005":{"en":"Many optional fields mean too many fields","ar":"كثرة الحقول الاختيارية تعني كثرة الحقول"},"MC-P01-028":{"en":"Mark every required field, at the field","ar":"ميّز كل حقل إلزامي، عند الحقل نفسه"},"MC-P01-029":{"en":"Unmarked optional fields get filled in anyway","ar":"الحقول الاختيارية غير المميّزة تُملأ على أي حال"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Salma joins","ar":"سلمى تشترك"},"body":{"en":"Salma loved the trial and decided to join. Now we really do need more from her.\n\nSome labels on our form have a star. Some don't. Nothing on the form says what the stars mean.","ar":"أحبّت سلمى التجربة وقرّرت الاشتراك. الآن نحتاج منها معلومات أكثر فعلًا.\n\nبعض التسميات في نموذجنا عليها نجمة، وبعضها لا. ولا شيء في النموذج يوضّح معنى النجوم."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-04","part":"try","rules":["R12"],"value":{"en":"Try first. Marking required fields (NN/g): be explicit; mark every field that must be completed. Marking optional fields as well is a helpful extra. Marking only the optional ones leaves people assuming.","ar":"جرّب أولًا. تمييز الحقول الإلزامية (NN/g): كن واضحًا؛ ميّز كل حقل يجب ملؤه. وتمييز الحقول الاختيارية أيضًا إضافة مفيدة. أما تمييز الاختيارية وحدها فيترك الناس يفترضون."},"ref":{"url":"https://www.nngroup.com/articles/required-fields/","quote":"Be as explicit and transparent as possible: for every single field that must be completed, mark it as required."},"scenario":{"en":"The emergency contact is required too; someone on my team forgot its star. Only the email and the fitness goal are optional.","ar":"رقم الطوارئ إلزامي أيضًا؛ لكن أحدًا في فريقي نسي نجمته. والحقلان الاختياريان الوحيدان هما البريد الإلكتروني والهدف الرياضي."},"prompt":{"en":"Try each way of marking the form. Which one should ship?","ar":"جرّب كل طريقة لتمييز الحقول. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]},"options":[{"id":"optonly","text":{"en":"Remove the stars; mark only the two optional fields","ar":"احذف النجوم؛ وميّز الحقلين الاختياريين فقط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal (optional)","ar":"هدفك الرياضي (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"note","text":{"en":"Remove the stars; add a note at the top","ar":"احذف النجوم؛ وأضف ملاحظة في الأعلى"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"small","text":{"en":"Name, mobile, national ID and emergency contact are required.","ar":"الاسم والموبايل والرقم القومي ورقم الطوارئ إلزامية."},"gap":"s"},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"both","text":{"en":"Star every required field, and mark the optional ones too","ar":"ضع نجمة على كل حقل إلزامي، وميّز الاختيارية أيضًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"},"gap":"s"},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number *","ar":"رقم للطوارئ *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal (optional)","ar":"هدفك الرياضي (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-028","when":["optonly"],"feedback":{"en":"Salma might not notice the word \"(optional)\" two fields down, and assume nothing is required. Then she finds out from errors. Mark every required field too.","ar":"قد لا تلاحظ سلمى كلمة «(اختياري)» بعد حقلين، فتفترض أن لا شيء إلزامي. ثم تكتشف ذلك من رسائل الخطأ. ميّز كل حقل إلزامي أيضًا."}},{"id":"MC-P01-028","when":["note"],"feedback":{"en":"People skip instructions at the top of a form, and forget them by the fourth field. Put the mark on the field itself.","ar":"يتخطّى الناس التعليمات أعلى النموذج، وينسونها عند الحقل الرابع. ضع العلامة على الحقل نفسه."}}],"hints":[{"en":"Look at the emergency contact: it's required, but nothing shows it.","ar":"انظر إلى رقم الطوارئ: إنه إلزامي، لكن لا شيء يوضّح ذلك."},{"en":"Each field should say for itself whether it's required or optional.","ar":"يجب أن يقول كل حقل بنفسه هل هو إلزامي أم اختياري."}],"correct":{"en":"Every field says what it is.","ar":"كل حقل يوضّح نوعه."},"explain":{"en":"Salma knows, at each field, whether she can skip it. No guessing, and no error message to learn the rules.","ar":"تعرف سلمى، عند كل حقل، هل تستطيع تخطّيه. بلا تخمين، وبلا رسالة خطأ لتتعلّم القواعد."},"speaker":"hana"},{"id":"S03","type":"card","part":"concept","icons":["eye","form","none","idea"],"title":{"en":"No one should have to guess","ar":"لا يجب أن يخمّن أحد"},"body":{"en":"People don't read the instructions at the top of a form, and those who do forget them. So the answer has to be on each field.\n\n- **Required:** put an asterisk (*) on every required field. People know what it means, and it takes little space.\n- **Optional:** add \"(optional)\" to the label. Otherwise many people fill it in anyway.\n- **Few optional fields:** if you have many, the form asks too much. Go back to Lesson 1.\n- **One truth:** the label and the check behind it must say the same thing.","ar":"الناس لا يقرؤون التعليمات أعلى النموذج، ومن يقرؤها ينساها. لذلك يجب أن تكون الإجابة عند كل حقل.\n\n- **الإلزامي:** ضع نجمة (*) على كل حقل إلزامي. الناس يعرفون معناها، وهي لا تأخذ مساحة كبيرة.\n- **الاختياري:** أضف «(اختياري)» إلى التسمية. وإلا سيملؤه كثيرون على أي حال.\n- **حقول اختيارية قليلة:** إذا كانت كثيرة، فالنموذج يطلب أكثر من اللازم. ارجع إلى الدرس 1.\n- **حقيقة واحدة:** يجب أن تقول التسمية والتحقق الذي وراءها الشيء نفسه."}},{"id":"S04","type":"tune","skill":"SK-P01-U01-04","part":"guided","rules":["R06","R15"],"value":{"en":"Marking required fields (NN/g): the asterisk is familiar, takes little space and looks different from the label text. A private style, like bold labels, is a code people have to crack.","ar":"تمييز الحقول الإلزامية (NN/g): النجمة مألوفة، ولا تأخذ مساحة كبيرة، وتبدو مختلفة عن نص التسمية. أما الأسلوب الخاص، مثل التسميات العريضة، فهو رمز على الناس أن يفكّوه."},"ref":{"url":"https://www.nngroup.com/articles/required-fields/","quote":"The asterisk has become very common on the web and users are familiar with its meaning."},"scenario":{"en":"A designer suggested a cleaner way to show the required fields on our form: make their labels bold.","ar":"اقترح مصمّم طريقة أنظف لإظهار الحقول الإلزامية في نموذجنا: أن تكون تسمياتها بخط عريض."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"bold","options":[{"id":"star","text":{"en":"An asterisk on each required label","ar":"نجمة على كل تسمية إلزامية"},"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"}]}},{"id":"bold","text":{"en":"Bold labels for required fields, regular for optional","ar":"تسميات عريضة للحقول الإلزامية، وعادية للاختيارية"},"mock":{"width":300,"blocks":[{"kind":"text","weight":"bold","text":{"en":"Full name","ar":"الاسم الكامل"}},{"kind":"field","text":"","gap":"xs"},{"kind":"text","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"text","weight":"bold","text":{"en":"National ID number","ar":"الرقم القومي"},"gap":"s"},{"kind":"field","text":"","gap":"xs"}]}},{"id":"red","text":{"en":"Red borders on required fields","ar":"حدود حمراء للحقول الإلزامية"},"mock":{"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","tone":"bad","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"}]}}],"answer":["star"],"misconceptions":[{"id":"MC-P01-003","when":["bold"],"feedback":{"en":"Bold doesn't mean \"required\" anywhere else, so Salma has to work out the code, and the difference is easy to miss. Use the mark people already know.","ar":"الخط العريض لا يعني «إلزامي» في أي مكان آخر، فعلى سلمى أن تفكّ الرمز، والفرق سهل أن يفوتها. استخدم العلامة التي يعرفها الناس."}},{"id":"MC-P01-003","when":["red"],"feedback":{"en":"A red border looks like an error before Salma has typed anything, and colour alone isn't seen by everyone. Use the asterisk.","ar":"الحدود الحمراء تبدو كخطأ قبل أن تكتب سلمى أي شيء، واللون وحده لا يراه الجميع. استخدم النجمة."}}],"hints":[{"en":"Which mark do people already know means required?","ar":"أي علامة يعرف الناس مسبقًا أنها تعني إلزامي؟"},{"en":"Bold and red can mean other things. Which one needs no explaining?","ar":"الخط العريض واللون الأحمر قد يعنيان أشياء أخرى. أيّها لا يحتاج شرحًا؟"}],"correct":{"en":"The familiar mark, on the label.","ar":"العلامة المألوفة، على التسمية."},"explain":{"en":"An asterisk is short, familiar, and stands out from the label. It works without a legend for most people, and a short one at the top helps the rest.","ar":"النجمة قصيرة ومألوفة وتبرز عن التسمية. وهي تعمل دون شرح لأغلب الناس، والشرح القصير في الأعلى يساعد الباقين."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U01-05","part":"guided","rules":["R06","R15"],"value":{"en":"Cognitive load in forms (NN/g): communicate requirements and set expectations upfront. A label that says optional sets an expectation; the check must keep it.","ar":"العبء الذهني في النماذج (NN/g): وضّح المتطلبات وحدّد التوقعات مسبقًا. والتسمية التي تقول اختياري تصنع توقّعًا؛ ويجب أن يلتزم به التحقق."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Communicate requirements and set expectations upfront."},"scenario":{"en":"Salma left \"Email (optional)\" empty and pressed Join now. The form stopped her. We send everything by text message; we never use the email.","ar":"تركت سلمى «البريد الإلكتروني (اختياري)» فارغًا وضغطت «اشترك الآن». فأوقفها النموذج. ونحن نرسل كل شيء برسائل نصية؛ ولا نستخدم البريد أبدًا."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","error":{"en":"Email is required.","ar":"البريد الإلكتروني إلزامي."}},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]},"options":[{"id":"label","text":{"en":"Change the label to \"Email *\"","ar":"غيّر التسمية إلى «البريد الإلكتروني *»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Email *","ar":"البريد الإلكتروني *"},"text":""},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep both; the error tells her what to do","ar":"أبقِ الاثنين؛ فرسالة الخطأ تخبرها بما تفعل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","error":{"en":"Email is required.","ar":"البريد الإلكتروني إلزامي."}},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"check","text":{"en":"Fix the check, so an empty email goes through","ar":"أصلِح التحقق، ليمرّ البريد الفارغ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":""},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"},{"kind":"small","color":"green","text":{"en":"Welcome to the gym, Salma!","ar":"أهلًا بك في النادي يا سلمى!"},"gap":"s"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-004","when":["label"],"feedback":{"en":"Now the label matches the check, but the gym never uses the email. You'd be asking for a field it doesn't need. Fix the check instead.","ar":"الآن تتّفق التسمية مع التحقق، لكن النادي لا يستخدم البريد أبدًا. فأنت تطلب حقلًا لا يحتاجه. أصلِح التحقق بدلًا من ذلك."}},{"id":"MC-P01-004","when":["keep"],"feedback":{"en":"The form promised one thing and did another. Salma learns the rules by failing, and stops trusting the other labels.","ar":"وعد النموذج بشيء وفعل غيره. فتتعلّم سلمى القواعد بالفشل، وتتوقّف عن الثقة في التسميات الأخرى."}}],"hints":[{"en":"The label and the check disagree. Which one matches what the gym needs?","ar":"التسمية والتحقّق لا يتّفقان. أيهما يطابق ما يحتاجه الجيم؟"},{"en":"The gym never uses the email. Should an empty email stop her, then?","ar":"الجيم لا يستخدم البريد الإلكتروني أبدًا. فهل يجب أن يوقفها بريد فارغ؟"}],"correct":{"en":"Decide what's needed, then make both agree.","ar":"قرّر ما تحتاجه، ثم اجعل الاثنين يتّفقان."},"explain":{"en":"This often happens when design and development set the required fields separately. Decide once, from the task, and write it in one place in the spec.","ar":"يحدث هذا كثيرًا حين يحدّد التصميم والتطوير الحقول الإلزامية كلٌّ على حدة. قرّر مرة واحدة، بناءً على المهمة، واكتبه في مكان واحد في المواصفات."},"speaker":"hana"},{"id":"S06","type":"tune","skill":"SK-P01-U01-01","part":"guided","speaker":"nour","rules":["R06","R15"],"value":{"en":"Forms usability (NN/g): limit the form to only one or two optional fields, and clearly label them. Four optional fields means the form asks too much.","ar":"سهولة استخدام النماذج (NN/g): اقتصر على حقل أو حقلين اختياريين فقط، وميّزهما بوضوح. وأربعة حقول اختيارية تعني أن النموذج يطلب أكثر من اللازم."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Limit the form to only 1 or 2 optional fields, and clearly label them as optional."},"scenario":{"en":"My clinic's booking form has four required fields and four optional ones. We use the insurance company and the note for the doctor. Nobody uses the other two.","ar":"نموذج الحجز في عيادتي فيه أربعة حقول إلزامية وأربعة اختيارية. ونحن نستخدم شركة التأمين والملاحظة للطبيب. ولا أحد يستخدم الحقلين الآخرين."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"mark","options":[{"id":"mark","text":{"en":"Keep all four, clearly marked optional","ar":"أبقِ الأربعة، مع تمييزها بوضوح كاختيارية"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name *","ar":"اسم المريض *"},"text":""},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Doctor *","ar":"الطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date and time *","ar":"التاريخ والوقت *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Insurance company (optional)","ar":"شركة التأمين (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the doctor (optional)","ar":"ملاحظة للطبيب (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you find us? (optional)","ar":"كيف وجدتنا؟ (اختياري)"},"text":"","gap":"s"}]}},{"id":"trim","text":{"en":"Remove the two nobody uses; mark the other two optional","ar":"احذف الحقلين اللذين لا يستخدمهما أحد؛ وميّز الآخرين كاختياريين"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name *","ar":"اسم المريض *"},"text":""},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Doctor *","ar":"الطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date and time *","ar":"التاريخ والوقت *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Insurance company (optional)","ar":"شركة التأمين (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the doctor (optional)","ar":"ملاحظة للطبيب (اختياري)"},"text":"","gap":"s"}]}},{"id":"required","text":{"en":"Make all eight required, so nothing needs a mark","ar":"اجعل الثمانية إلزامية، فلا يحتاج شيء إلى تمييز"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name *","ar":"اسم المريض *"},"text":""},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Doctor *","ar":"الطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date and time *","ar":"التاريخ والوقت *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Insurance company *","ar":"شركة التأمين *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the doctor *","ar":"ملاحظة للطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email *","ar":"البريد الإلكتروني *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you find us? *","ar":"كيف وجدتنا؟ *"},"text":"","gap":"s"}]}}],"answer":["trim"],"misconceptions":[{"id":"MC-P01-005","when":["mark"],"feedback":{"en":"The marks are clear, but people still read and think about four extra questions, two of them useless. Trim first, then mark.","ar":"العلامات واضحة، لكن الناس ما زالوا يقرؤون أربعة أسئلة إضافية ويفكّرون فيها، اثنان منها بلا فائدة. احذف أولًا، ثم ميّز."}},{"id":"MC-P01-001","when":["required"],"feedback":{"en":"Now people without insurance, or with nothing to tell the doctor, are stuck. Required means the task can't happen without it.","ar":"الآن من ليس لديه تأمين، أو ليس لديه ما يقوله للطبيب، سيتعطّل. والإلزامي يعني أن المهمة لا تتم بدونه."}}],"hints":[{"en":"Before marking anything, ask: does anyone use all eight fields?","ar":"قبل وضع أي علامة، اسأل: هل يستخدم أحد الحقول الثمانية كلها؟"},{"en":"A field nobody uses doesn't need a better mark.","ar":"الحقل الذي لا يستخدمه أحد لا يحتاج علامة أفضل."}],"correct":{"en":"Trim first, then mark what's left.","ar":"احذف أولًا، ثم ميّز ما تبقّى."},"explain":{"en":"Many optional fields are a warning sign. Remove the ones nobody uses; then one or two clearly marked extras are easy to skip.","ar":"كثرة الحقول الاختيارية علامة تحذير. احذف ما لا يستخدمه أحد؛ وحينها يسهل تخطّي إضافة أو إضافتين مميّزتين بوضوح."}},{"id":"S07","type":"compare","skill":"SK-P01-U01-04","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S04: stars on the required fields are needed, but not the whole job. Cognitive load in forms (NN/g): when marking isn't clear enough, many people feel obliged to answer optional questions.","ar":"مقارنة مع الخطوة 4: النجوم على الحقول الإلزامية ضرورية، لكنها ليست كل شيء. العبء الذهني في النماذج (NN/g): حين لا يكون التمييز واضحًا بما يكفي، يشعر كثيرون بأنهم ملزمون بالإجابة عن الأسئلة الاختيارية."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"When marking is not clear enough, many people feel obligated to answer optional questions."},"scenario":{"en":"Both versions of our form put a star on every required field. Salma has no fitness goal in mind yet.","ar":"النسختان من نموذجنا تضعان نجمة على كل حقل إلزامي. وليس لدى سلمى هدف رياضي محدّد بعد."},"prompt":{"en":"In which version can Salma see that she may skip the fitness goal?","ar":"في أي نسخة تستطيع سلمى أن ترى أنها يمكنها تخطّي الهدف الرياضي؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number *","ar":"رقم للطوارئ *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number *","ar":"رقم للطوارئ *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal (optional)","ar":"هدفك الرياضي (اختياري)"},"text":"","gap":"s"}]}},"answer":"b","reason":{"prompt":{"en":"Why doesn't the missing star in A tell her enough?","ar":"لماذا لا يكفي غياب النجمة في A لإخبارها؟"},"options":[{"id":"absence","text":{"en":"A missing mark is easy to overlook; a word she can read is not","ar":"غياب العلامة سهل أن يفوت؛ أما كلمة تقرؤها فلا"}},{"id":"longer","text":{"en":"Longer labels are always clearer","ar":"التسميات الأطول أوضح دائمًا"}},{"id":"trust","text":{"en":"The star in A is the wrong colour","ar":"النجمة في A بلون خاطئ"}}],"answer":["absence"],"misconceptions":[{"id":"MC-P01-029","when":["longer","trust"],"feedback":{"en":"The stars are the same in both. B wins because \"(optional)\" says it out loud, instead of relying on a star that isn't there.","ar":"النجوم واحدة في النسختين. B تفوز لأن «(اختياري)» تقولها صراحة، بدل الاعتماد على نجمة غير موجودة."}}]},"misconceptions":[{"id":"MC-P01-029","when":["a"],"feedback":{"en":"In A, Salma has to notice that a star is missing. Many people won't, and they'll invent a goal just to be safe.","ar":"في A، على سلمى أن تلاحظ أن نجمة غير موجودة. وكثيرون لن يلاحظوا، فسيخترعون هدفًا احتياطًا."}}],"hints":[{"en":"Look at the fitness goal label in each version.","ar":"انظر إلى تسمية الهدف الرياضي في كل نسخة."},{"en":"Does a missing star tell Salma as much as a word she can read?","ar":"هل يخبر غياب النجمة سلمى بقدر ما تخبرها كلمة تقرؤها؟"}],"correct":{"en":"Say \"optional\" in words too.","ar":"قل «اختياري» بالكلمات أيضًا."},"explain":{"en":"Stars tell people what they must fill in. \"(optional)\" tells them what they may skip. Together, nobody has to guess.","ar":"النجوم تخبر الناس بما يجب ملؤه. و«(اختياري)» تخبرهم بما يمكن تخطّيه. ومعًا، لا يحتاج أحد إلى التخمين."},"speaker":"hana"},{"id":"S08","type":"tune","skill":"SK-P01-U01-04","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Mobile input checklist (NN/g): is each field marked as required (*) or optional? Tamer's order has three required and two optional fields.","ar":"حالة جديدة. قائمة تحقّق حقول الهاتف (NN/g): هل كل حقل مميّز بأنه إلزامي (*) أو اختياري؟ في طلب تامر ثلاثة حقول إلزامية واثنان اختياريان."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"Is the field marked as required (*) or optional?"},"scenario":{"en":"In our app, Tamer's lunch order needs the address, the phone and the payment method. The note for the driver and the promo code are optional.","ar":"في تطبيقنا، يحتاج طلب غداء تامر العنوان والهاتف وطريقة الدفع. أما الملاحظة للسائق وكود الخصم فاختياريان."},"prompt":{"en":"Try each version of the order form. Which one should ship?","ar":"جرّب كل نسخة من نموذج الطلب. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":""},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method","ar":"طريقة الدفع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver","ar":"ملاحظة للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code","ar":"كود الخصم"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"gray","text":{"en":"Gray out the optional fields","ar":"اجعل الحقول الاختيارية رمادية باهتة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":""},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method","ar":"طريقة الدفع"},"text":"","gap":"s"},{"kind":"text","color":"faint","text":{"en":"Note for the driver","ar":"ملاحظة للسائق"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"text","color":"faint","text":{"en":"Promo code","ar":"كود الخصم"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"marked","text":{"en":"Star the three required; mark the other two optional","ar":"ضع نجمة على الثلاثة الإلزامية؛ وميّز الاثنين الآخرين كاختياريين"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"Delivery address *","ar":"عنوان التوصيل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Phone for the driver *","ar":"رقم هاتف للسائق *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method *","ar":"طريقة الدفع *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver (optional)","ar":"ملاحظة للسائق (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code (optional)","ar":"كود الخصم (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"top","text":{"en":"Add \"Fields 1 to 3 are required\" above the form","ar":"أضف «الحقول من 1 إلى 3 إلزامية» أعلى النموذج"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Fields 1 to 3 are required.","ar":"الحقول من 1 إلى 3 إلزامية."}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method","ar":"طريقة الدفع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver","ar":"ملاحظة للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code","ar":"كود الخصم"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}}],"answer":["marked"],"misconceptions":[{"id":"MC-P01-003","when":["gray"],"feedback":{"en":"Faded fields look disabled, so Tamer may think he can't type a note at all. And the faint labels are hard to read. Say it in words.","ar":"الحقول الباهتة تبدو معطّلة، فقد يظن تامر أنه لا يستطيع كتابة ملاحظة أصلًا. والتسميات الباهتة صعبة القراءة. قلها بالكلمات."}},{"id":"MC-P01-028","when":["top"],"feedback":{"en":"Tamer has to count fields and remember the rule. Most people skip that line anyway. Mark each field.","ar":"على تامر أن يعدّ الحقول ويتذكّر القاعدة. وأغلب الناس يتخطّون هذا السطر على أي حال. ميّز كل حقل."}}],"hints":[{"en":"Check each field: can Tamer tell from the field itself whether he must fill it?","ar":"افحص كل حقل: هل يعرف تامر من الحقل نفسه إن كان عليه ملؤه؟"},{"en":"Gray looks disabled, and a note at the top is easy to miss.","ar":"اللون الرمادي يبدو معطّلًا، والملاحظة في الأعلى سهلة التجاهل."}],"correct":{"en":"Each field says it: * or (optional).","ar":"كل حقل يقولها: * أو (اختياري)."},"explain":{"en":"The same rule works on every form: a star on each required field, and \"(optional)\" on the few that aren't.","ar":"القاعدة نفسها تعمل في كل نموذج: نجمة على كل حقل إلزامي، و«(اختياري)» على القليل غير الإلزامي."}},{"id":"S09","type":"card","part":"recap","icons":["eye","form","none","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Mark it on the field:** a star on every required field, not a note at the top.\n- **The familiar mark:** used the asterisk, not bold, colour or gray.\n- **One truth:** made the label and the check agree.\n- **Trim first:** cut unused optional fields, then marked the rest.\n- **Say optional:** wrote \"(optional)\" so people know what they can skip.\n\nNext lesson: asking in a way people can answer.","ar":"- **ميّزه عند الحقل:** نجمة على كل حقل إلزامي، لا ملاحظة في الأعلى.\n- **العلامة المألوفة:** استخدمت النجمة، لا الخط العريض أو اللون أو الرمادي.\n- **حقيقة واحدة:** جعلت التسمية والتحقق يتّفقان.\n- **احذف أولًا:** حذفت الحقول الاختيارية غير المستخدمة، ثم ميّزت الباقي.\n- **قل اختياري:** كتبت «(اختياري)» ليعرف الناس ما يمكنهم تخطّيه.\n\nالدرس التالي: كيف تسأل بطريقة يستطيع الناس الإجابة عنها."}}]}$uxg$::jsonb),
  ($uxg$P01-U01-L03$uxg$, $uxg$fde41a61922f11ac82300eb3dd640665c40f9da86efab1a8d5f153f36958a7ab$uxg$, $uxg${"id":"P01-U01-L03","mode":"lesson","minutes":8,"title":{"en":"Ask so people can answer","ar":"اسأل بطريقة يستطيع الناس الإجابة عنها"},"speaker":"sara","review_labels":{"MC-P01-006":{"en":"Not everyone's name has a first and last part","ar":"ليس لكل اسم جزء أول وجزء أخير"},"MC-P01-007":{"en":"Let the system clean up the format, not the person","ar":"دع النظام ينظّف الصيغة، لا الشخص"},"MC-P01-008":{"en":"Ask about the real need, in everyday words","ar":"اسأل عن الحاجة الفعلية بكلمات يومية"},"MC-P01-030":{"en":"Write the month as a word","ar":"اكتب الشهر بالحروف"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Abdelrahman's library card","ar":"بطاقة مكتبة عبد الرحمن"},"body":{"en":"I'm redesigning the city library's sign-up form. Abdelrahman Mohamed El-Sayed Hassan is getting a library card. His ID shows four names: his own, his father's, his grandfather's and the family name.\n\nOur form gives him two boxes.","ar":"أعيد تصميم نموذج التسجيل في مكتبة المدينة. يستخرج عبد الرحمن محمد السيد حسن بطاقة مكتبة، وبطاقة هويته فيها أربعة أسماء: اسمه، واسم أبيه، واسم جدّه، واسم العائلة.\n\nونموذجنا يعطيه خانتين."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-06","part":"try","rules":["R12"],"value":{"en":"Try first. International sites (NN/g): separate first-name and last-name fields are a prescription for confusion; some people have one name, others several. One full-name field fits every pattern.","ar":"جرّب أولًا. المواقع الدولية (NN/g): الحقول المنفصلة للاسم الأول واسم العائلة وصفة للارتباك؛ فبعض الناس لهم اسم واحد، وآخرون عدة أسماء. وحقل واحد للاسم الكامل يناسب كل الأنماط."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"Offering separate fields for first name and last name is a prescription for confusion."},"prompt":{"en":"Try each way of asking for his name. Which one should ship?","ar":"جرّب كل طريقة لطلب اسمه. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]},"options":[{"id":"four","text":{"en":"Four boxes: name, father, grandfather, family","ar":"أربع خانات: الاسم، الأب، الجد، العائلة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Father's name","ar":"اسم الأب"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Grandfather's name","ar":"اسم الجد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Family name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}},{"id":"full","text":{"en":"One field: \"Full name, as on your ID\"","ar":"حقل واحد: «الاسم الكامل، كما في بطاقتك»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"Full name, as on your ID","ar":"الاسم الكامل، كما في بطاقتك"},"filled":true,"text":{"en":"Abdelrahman Mohamed El-Sayed Hassan","ar":"عبد الرحمن محمد السيد حسن"},"gap":"m"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}},{"id":"rename","text":{"en":"Keep two boxes, renamed \"Given name\" and \"Family name\"","ar":"أبقِ خانتين، باسم «الاسم» و«اسم العائلة»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"Given name","ar":"الاسم"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Family name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}}],"answer":["full"],"misconceptions":[{"id":"MC-P01-006","when":["four"],"feedback":{"en":"Four boxes fit Abdelrahman, and break for the next person: someone with two names, or five. One field fits everyone.","ar":"أربع خانات تناسب عبد الرحمن، وتفشل مع الشخص التالي: من له اسمان، أو خمسة. والحقل الواحد يناسب الجميع."}},{"id":"MC-P01-006","when":["rename"],"feedback":{"en":"New names, same problem. Where do \"Mohamed El-Sayed\" go? He has to guess, and may not match his ID.","ar":"أسماء جديدة، والمشكلة نفسها. أين يكتب «محمد السيد»؟ عليه أن يخمّن، وقد لا يطابق ما يكتبه بطاقته."}}],"hints":[{"en":"Count the names on his ID, then count the boxes.","ar":"عُدّ الأسماء في بطاقته، ثم عُدّ المربعات."},{"en":"People have different numbers of names. What fits them all?","ar":"يختلف عدد الأسماء من شخص لآخر. ما الذي يناسبهم جميعًا؟"}],"correct":{"en":"One field, typed as on his ID.","ar":"حقل واحد، يُكتب كما في بطاقته."},"explain":{"en":"Names come in many shapes. One field lets each person write theirs exactly, and the library can still ask \"What should we call you?\" if it wants a short name.","ar":"الأسماء تأتي بأشكال كثيرة. والحقل الواحد يتيح لكل شخص كتابة اسمه كما هو تمامًا، وتستطيع المكتبة مع ذلك أن تسأل «بماذا نناديك؟» إذا أرادت اسمًا قصيرًا."}},{"id":"S03","type":"card","part":"concept","icons":["form","idea","eye","clock"],"title":{"en":"Fit the question to the answer people have","ar":"اجعل السؤال يناسب الإجابة التي لدى الناس"},"body":{"en":"A question is easy when it matches how people already hold the answer.\n\n- **Names:** one \"Full name\" field fits every naming pattern.\n- **Formats:** let people type a phone number the way they write it, with spaces, dashes or a country code. The system tidies it.\n- **Words:** labels should make sense at first read. If someone has to look a word up, change the word.\n- **Dates:** write the month as a word. 03/04 could be March or April.","ar":"يكون السؤال سهلًا حين يطابق الطريقة التي يحمل بها الناس الإجابة.\n\n- **الأسماء:** حقل واحد «الاسم الكامل» يناسب كل أنماط الأسماء.\n- **الصيغ:** دع الناس يكتبون رقم الهاتف كما يكتبونه عادة، بمسافات أو شرطات أو رمز الدولة. والنظام يرتّبه.\n- **الكلمات:** يجب أن تُفهم التسميات من أول قراءة. إذا احتاج أحد أن يبحث عن معنى كلمة، فغيّر الكلمة.\n- **التواريخ:** اكتب الشهر بالحروف. فـ 03/04 قد تعني مارس أو أبريل."}},{"id":"S04","type":"tune","skill":"SK-P01-U01-07","part":"guided","rules":["R06","R15"],"value":{"en":"Mobile input checklist (NN/g): let users enter a phone number in whatever format they like, and autoformat it for them. Rejecting spaces makes people do the system's work.","ar":"قائمة تحقّق حقول الهاتف (NN/g): دع المستخدمين يُدخلون رقم الهاتف بأي صيغة يريدونها، ونسّقه لهم تلقائيًا. ورفض المسافات يجعل الناس يقومون بعمل النظام."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"Do you allow users to enter it in whatever format they like?"},"scenario":{"en":"In testing, Abdelrahman copied his number from his contacts: ⁦010 1234 5678⁩. Our form rejected it because of the spaces.","ar":"في الاختبار، نسخ عبد الرحمن رقمه من جهات الاتصال: ⁦010 1234 5678⁩. فرفضه نموذجنا بسبب المسافات."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 1234 5678⁩","error":{"en":"Invalid number.","ar":"رقم غير صالح."}}]},"options":[{"id":"hint","text":{"en":"Add a hint: \"Digits only, no spaces\"","ar":"أضف تلميحًا: «أرقام فقط، بدون مسافات»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Digits only, no spaces.","ar":"أرقام فقط، بدون مسافات."}}]}},{"id":"boxes","text":{"en":"Split it into three boxes: 3, 4 and 4 digits","ar":"قسّمه إلى ثلاث خانات: 3 و4 و4 أرقام"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Mobile number","ar":"رقم الموبايل"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","text":"010"},{"kind":"field","text":""},{"kind":"field","text":""}]}]}},{"id":"accept","text":{"en":"Accept it as typed; the system removes the spaces","ar":"اقبله كما كُتب؛ والنظام يحذف المسافات"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 1234 5678⁩"},{"kind":"small","color":"green","text":{"en":"✓ Saved as 01012345678","ar":"✓ حُفظ هكذا: 01012345678"},"gap":"xs"}]}}],"answer":["accept"],"misconceptions":[{"id":"MC-P01-007","when":["hint"],"feedback":{"en":"The number was never wrong. Now Abdelrahman has to delete the spaces by hand, on a phone keyboard. Let the system do it.","ar":"الرقم لم يكن خاطئًا أصلًا. والآن على عبد الرحمن أن يحذف المسافات بيده، على لوحة مفاتيح الهاتف. دع النظام يفعل ذلك."}},{"id":"MC-P01-007","when":["boxes"],"feedback":{"en":"He can't paste the number in one go any more, and he has to jump between boxes. One field, any format.","ar":"لم يعد يستطيع لصق الرقم دفعة واحدة، وعليه أن يتنقّل بين الخانات. حقل واحد، بأي صيغة."}}],"hints":[{"en":"Who should remove the spaces: Abdelrahman or the system?","ar":"من يجب أن يزيل المسافات: عبد الرحمن أم النظام؟"},{"en":"A hint or extra boxes still make him change the way he writes it.","ar":"التلميح أو المربعات الإضافية ما زالت تجبره على تغيير طريقة كتابته."}],"correct":{"en":"Accept the way people write it.","ar":"اقبل الطريقة التي يكتب بها الناس."},"explain":{"en":"People copy numbers from contacts and messages, spaces included. Removing spaces is a simple job for the system and an annoying one for a person.","ar":"ينسخ الناس الأرقام من جهات الاتصال والرسائل، بالمسافات. وحذف المسافات مهمة بسيطة للنظام ومزعجة للإنسان."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U01-08","part":"guided","rules":["R06","R15"],"value":{"en":"Cognitive load in forms (NN/g): labels and instructions should be immediately understandable; plain language helps everyone. Internal terms need a translation, not a tooltip.","ar":"العبء الذهني في النماذج (NN/g): يجب أن تُفهم التسميات والتعليمات فورًا؛ واللغة البسيطة تساعد الجميع. والمصطلحات الداخلية تحتاج إلى ترجمة، لا إلى تلميح منبثق."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Form labels and instructions should be immediately understandable."},"scenario":{"en":"The library's form asks for a \"Patron classification\": A, B or C. The staff told me B means students and under-18s, who get the card free.","ar":"يطلب نموذج المكتبة «تصنيف المستفيد»: A أو B أو C. وأخبرني الموظفون أن B تعني الطلاب ومن هم دون 18 عامًا، وهؤلاء يحصلون على البطاقة مجانًا."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"code","options":[{"id":"plain","text":{"en":"Ask the real question in everyday words","ar":"اطرح السؤال الحقيقي بكلمات يومية"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Are you a student, or under 18?","ar":"هل أنت طالب، أو عمرك أقل من 18 عامًا؟"}},{"kind":"small","text":{"en":"If yes, your card is free.","ar":"إذا كانت الإجابة نعم، فبطاقتك مجانية."},"gap":"xs"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":{"en":"Yes","ar":"نعم"}},{"kind":"chip","text":{"en":"No","ar":"لا"}}]}]}},{"id":"code","text":{"en":"Keep the classification, with an ⓘ that explains it","ar":"أبقِ التصنيف، مع ⓘ يشرحه"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Patron classification ⓘ","ar":"تصنيف المستفيد ⓘ"}},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":"A"},{"kind":"chip","text":"B"},{"kind":"chip","text":"C"}]}]}},{"id":"table","text":{"en":"Keep it, with a table of the categories above","ar":"أبقِه، مع جدول للتصنيفات في الأعلى"},"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"A: adults · B: students and under-18s · C: visitors from other cities","ar":"A: البالغون · B: الطلاب ومن هم دون 18 · C: الزوّار من مدن أخرى"}},{"kind":"small","weight":"bold","text":{"en":"Patron classification","ar":"تصنيف المستفيد"},"gap":"s"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":"A"},{"kind":"chip","text":"B"},{"kind":"chip","text":"C"}]}]}}],"answer":["plain"],"misconceptions":[{"id":"MC-P01-008","when":["code"],"feedback":{"en":"The label still means nothing until Abdelrahman finds and opens the ⓘ. Ask in words he already understands.","ar":"التسمية ما زالت بلا معنى حتى يجد عبد الرحمن الـ ⓘ ويفتحه. اسأل بكلمات يفهمها بالفعل."}},{"id":"MC-P01-008","when":["table"],"feedback":{"en":"Now he reads a table, translates it, and remembers the letter. The library only needs to know one thing: student or under 18?","ar":"الآن يقرأ جدولًا، ويترجمه، ويتذكّر الحرف. والمكتبة تحتاج معرفة شيء واحد فقط: طالب أو دون 18؟"}}],"hints":[{"en":"Would Abdelrahman understand this classification at first read?","ar":"هل سيفهم عبد الرحمن هذا التصنيف من أول قراءة؟"},{"en":"What does the library really want to know about him?","ar":"ما الذي تريد المكتبة معرفته عنه فعلًا؟"}],"correct":{"en":"Ask what you need to know, in his words.","ar":"اسأل عمّا تحتاج معرفته، بكلماته هو."},"explain":{"en":"Internal codes make sense to staff. A plain question gets the same answer, faster, and tells him why it matters: the card is free.","ar":"الرموز الداخلية مفهومة للموظفين. والسؤال البسيط يحصل على الإجابة نفسها، أسرع، ويخبره لماذا يهم: البطاقة مجانية."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U01-08","part":"guided","rules":["R06","R15"],"value":{"en":"International sites (NN/g): for dates, always spell out the name of the month. A numeric date like 03/04 reads as March or April depending on where you're from.","ar":"المواقع الدولية (NN/g): في التواريخ، اكتب اسم الشهر دائمًا. فالتاريخ الرقمي مثل 03/04 يُقرأ مارس أو أبريل حسب بلدك."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"For dates, the main guideline is: Always spell out the name of the month."},"scenario":{"en":"I watched Abdelrahman pick his date of birth, 3 April 2005, from a calendar. The field then shows the date he picked, so he can check it.","ar":"شاهدت عبد الرحمن يختار تاريخ ميلاده، 3 أبريل 2005، من تقويم. ثم يعرض الحقل التاريخ الذي اختاره ليتحقّق منه."},"prompt":{"en":"Try each way of showing the date. Which one should ship?","ar":"جرّب كل طريقة لعرض التاريخ. أيّها يجب أن تُطلق؟"},"start":"slash","options":[{"id":"slash","text":{"en":"03/04/2005","ar":"03/04/2005"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":"03/04/2005"}]}},{"id":"iso","text":{"en":"2005-04-03","ar":"2005-04-03"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":"2005-04-03"}]}},{"id":"words","text":{"en":"3 April 2005","ar":"3 أبريل 2005"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":{"en":"3 April 2005","ar":"3 أبريل 2005"}}]}}],"answer":["words"],"misconceptions":[{"id":"MC-P01-030","when":["slash"],"feedback":{"en":"Is that 3 April or 4 March? It depends on the country the reader learned dates in. He can't be sure he picked the right day.","ar":"هل هو 3 أبريل أم 4 مارس؟ يعتمد ذلك على البلد الذي تعلّم فيه القارئ التواريخ. فلا يستطيع التأكّد أنه اختار اليوم الصحيح."}},{"id":"MC-P01-030","when":["iso"],"feedback":{"en":"Clear to a database, but most people don't read dates that way, and the middle number still needs decoding. Write the month.","ar":"واضح لقاعدة البيانات، لكن أغلب الناس لا يقرؤون التواريخ هكذا، والرقم الأوسط ما زال يحتاج إلى فكّ. اكتب الشهر."}}],"hints":[{"en":"Read 03/04/2005 the way someone from another country might.","ar":"اقرأ 03/04/2005 كما قد يقرؤها شخص من بلد آخر."},{"en":"Which format can be read only one way?","ar":"أي صيغة لا تُقرأ إلا بطريقة واحدة؟"}],"correct":{"en":"Write the month as a word.","ar":"اكتب الشهر بالحروف."},"explain":{"en":"\"3 April 2005\" has only one reading, in any country. It costs a few more characters and removes all doubt.","ar":"«3 أبريل 2005» لها قراءة واحدة فقط، في أي بلد. وتكلّف حروفًا قليلة إضافية وتُزيل كل شك."},"speaker":"sara"},{"id":"S07","type":"compare","skill":"SK-P01-U01-07","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S04: accepting spaces is not the whole job. International sites (NN/g): allow international phone numbers with a varying number of digits and a country code.","ar":"مقارنة مع الخطوة 4: قبول المسافات ليس كل المطلوب. المواقع الدولية (NN/g): اسمح بأرقام الهواتف الدولية بعدد أرقام متغيّر ورمز دولة."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"For phone numbers, allow for international numbers containing a varying number of digits and a country code."},"scenario":{"en":"The library asks for an emergency contact. Abdelrahman's brother works abroad, and his number starts with a country code. Both of my versions accept spaces.","ar":"تطلب المكتبة رقمًا للطوارئ. وأخو عبد الرحمن يعمل في الخارج، ورقمه يبدأ برمز دولة. والنسختان اللتان صمّمتهما تقبلان المسافات."},"prompt":{"en":"Which emergency contact field should ship?","ar":"أي حقل لرقم الطوارئ يجب أن يُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"filled":true,"text":"⁦+971 50 123 4567⁩","error":{"en":"Use 11 digits starting with 0.","ar":"استخدم 11 رقمًا تبدأ بـ 0."}}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"filled":true,"text":"⁦+971 50 123 4567⁩"},{"kind":"small","color":"green","text":{"en":"✓ Saved","ar":"✓ تم الحفظ"},"gap":"xs"}]}},"answer":"b","reason":{"prompt":{"en":"What does A get wrong, even though it accepts spaces?","ar":"ما خطأ A، مع أنه يقبل المسافات؟"},"options":[{"id":"local","text":{"en":"It assumes every number is a local mobile","ar":"يفترض أن كل رقم موبايل محلي"}},{"id":"plus","text":{"en":"The + sign is not a digit","ar":"علامة + ليست رقمًا"}},{"id":"long","text":{"en":"The error message is too long","ar":"رسالة الخطأ طويلة جدًا"}}],"answer":["local"],"misconceptions":[{"id":"MC-P01-007","when":["plus","long"],"feedback":{"en":"The real problem is the rule: 11 digits starting with 0 fits only local numbers. Real contacts can be anywhere.","ar":"المشكلة الحقيقية هي القاعدة: 11 رقمًا تبدأ بـ 0 تناسب الأرقام المحلية فقط. وجهات الاتصال الحقيقية قد تكون في أي مكان."}}]},"misconceptions":[{"id":"MC-P01-007","when":["a"],"feedback":{"en":"A is flexible about spaces but still rejects a real number. Abdelrahman can't give the contact he actually has.","ar":"A مرن مع المسافات لكنه ما زال يرفض رقمًا حقيقيًا. فلا يستطيع عبد الرحمن إعطاء جهة الاتصال التي لديه فعلًا."}}],"hints":[{"en":"Look at his brother's number: how does it start, and how long is it?","ar":"انظر إلى رقم أخيه: بماذا يبدأ، وكم طوله؟"},{"en":"Both accept spaces. What else does a number from abroad need?","ar":"كلا النموذجين يقبل المسافات. ماذا يحتاج الرقم من الخارج أيضًا؟"}],"correct":{"en":"Flexible format and flexible length.","ar":"صيغة مرنة وطول مرن."},"explain":{"en":"Check that a number is a phone number, not that it looks like yours. Country codes and different lengths are normal.","ar":"تحقّق من أن الرقم رقم هاتف، لا من أنه يشبه أرقام بلدك. فرموز الدول والأطوال المختلفة أمر طبيعي."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P01-U01-08","part":"independent","rules":["R14","R19"],"value":{"en":"New case. Cognitive load in forms (NN/g): ambiguity slows users down. Laila's booking form mixes an internal term, a strict phone format and split name fields.","ar":"حالة جديدة. العبء الذهني في النماذج (NN/g): الغموض يُبطئ المستخدمين. ونموذج حجز ليلى يجمع مصطلحًا داخليًا وصيغة هاتف صارمة وحقلين منفصلين للاسم."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Ambiguity slows users down."},"scenario":{"en":"My next client is a home cleaning company. Laila is booking a cleaning, and the company needs her name, her phone, and the size of her flat to send the right team.","ar":"عميلي التالي شركة تنظيف منزلي. تحجز ليلى تنظيفًا، وتحتاج الشركة اسمها وهاتفها وحجم شقتها لترسل الفريق المناسب."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":""},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Format: 01XXXXXXXXX","ar":"الصيغة: 01XXXXXXXXX"},"gap":"s"},{"kind":"field","label":{"en":"Unit typology","ar":"تصنيف الوحدة"},"text":"","gap":"s"}]},"options":[{"id":"help","text":{"en":"Keep the fields; add help text under each one","ar":"أبقِ الحقول؛ وأضف نصًا توضيحيًا تحت كل واحد"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","hint":{"en":"Your first given name","ar":"اسمك الأول"}},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","hint":{"en":"Your family name only","ar":"اسم العائلة فقط"},"gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Format: 01XXXXXXXXX, no spaces","ar":"الصيغة: 01XXXXXXXXX، بدون مسافات"},"gap":"s"},{"kind":"field","label":{"en":"Unit typology","ar":"تصنيف الوحدة"},"text":"","hint":{"en":"S1, S2 or S3, by floor area","ar":"S1 أو S2 أو S3، حسب المساحة"},"gap":"s"}]}},{"id":"name","text":{"en":"Fix only the name; one Full name field","ar":"أصلِح الاسم فقط؛ حقل واحد للاسم الكامل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Format: 01XXXXXXXXX","ar":"الصيغة: 01XXXXXXXXX"},"gap":"s"},{"kind":"field","label":{"en":"Unit typology","ar":"تصنيف الوحدة"},"text":"","gap":"s"}]}},{"id":"plain","text":{"en":"One name field, any phone format, and ask how many bedrooms","ar":"حقل اسم واحد، وأي صيغة للهاتف، واسأل عن عدد غرف النوم"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"small","weight":"bold","text":{"en":"How many bedrooms?","ar":"كم عدد غرف النوم؟"},"gap":"s"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":"1"},{"kind":"chip","text":"2"},{"kind":"chip","text":"3"},{"kind":"chip","text":"4+"}]}]}}],"answer":["plain"],"misconceptions":[{"id":"MC-P01-008","when":["help"],"feedback":{"en":"Help text explains the problems instead of removing them. Laila still has to split her name, strip spaces and decode \"S2\".","ar":"النص التوضيحي يشرح المشكلات بدل أن يُزيلها. فما زال على ليلى أن تقسم اسمها، وتحذف المسافات، وتفكّ «S2»."}},{"id":"MC-P01-008","when":["name"],"feedback":{"en":"The name is fixed, but \"Unit typology\" still means nothing to her, and the phone still has to be typed the system's way.","ar":"الاسم أُصلح، لكن «تصنيف الوحدة» ما زال بلا معنى لها، والهاتف ما زال يجب أن يُكتب بطريقة النظام."}}],"hints":[{"en":"Check all three questions, not just one: name, phone and flat size.","ar":"افحص الأسئلة الثلاثة لا سؤالًا واحدًا: الاسم والهاتف ومساحة الشقة."},{"en":"Help text explains a hard question. Could the questions be easy instead?","ar":"النص المساعد يشرح سؤالًا صعبًا. هل يمكن أن تكون الأسئلة سهلة بدلًا من ذلك؟"}],"correct":{"en":"Every question in her words.","ar":"كل سؤال بكلماتها هي."},"explain":{"en":"Laila knows her name, her number and how many bedrooms she has. The company turns that into its own codes behind the scenes.","ar":"تعرف ليلى اسمها ورقمها وعدد غرف نومها. والشركة تحوّل ذلك إلى رموزها الخاصة في الخلفية."},"speaker":"sara"},{"id":"S09","type":"card","part":"recap","icons":["form","idea","eye","clock"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **One name field:** let every name fit, as written on the ID.\n- **Any format:** accepted the phone number as typed, and let the system tidy it.\n- **Everyday words:** replaced an internal code with the real question.\n- **Months in words:** wrote dates that have only one reading.\n- **Any country:** accepted country codes and different lengths.\n\nNext: the unit skill check.","ar":"- **حقل اسم واحد:** جعلت كل اسم يتّسع، كما هو مكتوب في البطاقة.\n- **أي صيغة:** قبلت رقم الهاتف كما كُتب، وتركت النظام يرتّبه.\n- **كلمات يومية:** استبدلت رمزًا داخليًا بالسؤال الحقيقي.\n- **الشهر بالحروف:** كتبت تواريخ لها قراءة واحدة فقط.\n- **أي بلد:** قبلت رموز الدول والأطوال المختلفة.\n\nالتالي: اختبار المهارة للوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U01-L04$uxg$, $uxg$353030358ebf1b930c331972aebf582ad38ba9ad0c4470f72e43e418eccd0d0c$uxg$, $uxg${"id":"P01-U01-L04","mode":"check","minutes":7,"title":{"en":"Skill check: ask only what you need","ar":"اختبار المهارة: اسأل فقط عمّا تحتاجه"},"speaker":"sara","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Samir's football camp form","ar":"نموذج معسكر كرة القدم لسمير"},"body":{"en":"A football academy asked me to fix its sign-up form. Samir wants to register his 9-year-old son, Ziad, for a summer camp, and this is the form he gets.\n\nYour job: help me fix it, one decision at a time.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"طلبت مني أكاديمية لكرة القدم إصلاح نموذج التسجيل. يريد سمير تسجيل ابنه زياد، 9 سنوات، في معسكر صيفي، وهذا هو النموذج الذي يظهر له.\n\nمهمّتك: ساعدني على إصلاحه، قرارًا بعد قرار.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name","ar":"اسم المدرسة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Monthly family income","ar":"دخل الأسرة الشهري"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child","ar":"صورة الطفل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-01","part":"check","rules":["R19"],"value":{"en":"Skill check, EAS framework (NN/g): ask whether each question is needed now. Income has no use; the school isn't used; the badge photo can wait until the first day.","ar":"اختبار مهارة، إطار EAS (NN/g): اسأل هل كل سؤال مطلوب الآن. الدخل لا فائدة له؛ والمدرسة لا تُستخدم؛ وصورة البطاقة يمكن أن تنتظر حتى اليوم الأول."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Do we need this information now?"},"scenario":{"en":"The academy told me what it needs to register a child: who Ziad is, his age group, a parent to call, and any health needs. The badge photo is taken on the first day. Nothing uses the school or the income.","ar":"أخبرتني الأكاديمية بما تحتاجه لتسجيل الطفل: من هو زياد، وفئته العمرية، ووليّ أمر للاتصال به، وأي احتياجات صحية. وصورة البطاقة تُلتقط في اليوم الأول. ولا شيء يستخدم المدرسة أو الدخل."},"prompt":{"en":"Try each version of the form. Which one should ship?","ar":"جرّب كل نسخة من النموذج. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name","ar":"اسم المدرسة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Monthly family income","ar":"دخل الأسرة الشهري"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child","ar":"صورة الطفل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]},"options":[{"id":"optional","text":{"en":"Keep all seven; mark school, income and photo optional","ar":"أبقِ السبعة؛ واجعل المدرسة والدخل والصورة اختيارية"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name (optional)","ar":"اسم المدرسة (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Monthly family income (optional)","ar":"دخل الأسرة الشهري (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child (optional)","ar":"صورة الطفل (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"income","text":{"en":"Remove the income only","ar":"احذف الدخل فقط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name","ar":"اسم المدرسة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child","ar":"صورة الطفل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"needed","text":{"en":"Keep the four it needs now; the photo on day one","ar":"أبقِ الأربعة المطلوبة الآن؛ والصورة في اليوم الأول"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"},{"kind":"small","text":{"en":"Day one: badge photo at the gate","ar":"اليوم الأول: صورة البطاقة عند البوابة"},"gap":"l"}]}}],"answer":["needed"],"misconceptions":[{"id":"MC-P01-005","when":["optional"],"feedback":{"en":"Marked optional, they're still on the form, and many parents will fill them in just in case. Remove what has no use; move what can wait.","ar":"حتى مع وسمها كاختيارية، ما زالت في النموذج، وسيملؤها كثير من الآباء احتياطًا. احذف ما لا فائدة له؛ وانقل ما يمكن أن ينتظر."}},{"id":"MC-P01-002","when":["income"],"feedback":{"en":"A good start, but the school is never used, and the photo isn't needed until the first day. Ask only what registering needs.","ar":"بداية جيدة، لكن المدرسة لا تُستخدم أبدًا، والصورة لا تلزم قبل اليوم الأول. اسأل فقط عمّا يحتاجه التسجيل."}}],"explain":{"en":"From Lesson 1: keep what the task needs now, move what can wait, and remove what nobody uses.","ar":"من الدرس 1: أبقِ ما تحتاجه المهمة الآن، وانقل ما يمكن أن ينتظر، واحذف ما لا يستخدمه أحد."},"speaker":"sara"},{"id":"S03","type":"tune","skill":"SK-P01-U01-03","part":"check","rules":["R19"],"value":{"en":"Skill check, EAS framework (NN/g): a simple, clear explanation reassures people and builds trust. Health details are personal; say who sees them and why.","ar":"اختبار مهارة، إطار EAS (NN/g): الشرح البسيط الواضح يطمئن الناس ويبني الثقة. والتفاصيل الصحية شخصية؛ فوضّح من يراها ولماذا."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"A simple, clear explanation reassures users, builds trust, and helps them understand the rationale behind each question."},"scenario":{"en":"Ziad has a mild nut allergy. Samir told me he isn't sure he wants to write it down for an academy he doesn't know yet.","ar":"لدى زياد حساسية خفيفة من المكسّرات. وأخبرني سمير أنه لا يعرف هل يريد كتابتها لأكاديمية لا يعرفها بعد."},"prompt":{"en":"Try each version of the health field. Which one should ship?","ar":"جرّب كل نسخة من حقل الصحة. أيّها يجب أن يُطلق؟"},"start":"bare","options":[{"id":"why","text":{"en":"Say who sees it and what it's for","ar":"وضّح من يراه وما الغرض منه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","hint":{"en":"Only Ziad's coaches see this, so they know what to do in an emergency.","ar":"لا يرى هذا إلا مدرّبو زياد، ليعرفوا ماذا يفعلون في حالة طارئة."}}]}},{"id":"bare","text":{"en":"Just the label","ar":"التسمية فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":""}]}},{"id":"legal","text":{"en":"Add \"We collect this as required by our policies\"","ar":"أضف «نجمع هذا وفقًا لسياساتنا»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","hint":{"en":"We collect this as required by our policies.","ar":"نجمع هذا وفقًا لسياساتنا."}}]}}],"answer":["why"],"misconceptions":[{"id":"MC-P01-027","when":["bare"],"feedback":{"en":"Samir has to guess who reads it and why. A worried parent may leave it vague, which is the worst outcome for Ziad.","ar":"على سمير أن يخمّن من يقرؤه ولماذا. والوالد القلق قد يكتبه بشكل مبهم، وهذه أسوأ نتيجة لزياد."}},{"id":"MC-P01-027","when":["legal"],"feedback":{"en":"That says the academy wants it, not why it helps Ziad. Name who sees it and what they'll do with it.","ar":"هذا يقول إن الأكاديمية تريده، لا لماذا يساعد زياد. اذكر من يراه وماذا سيفعل به."}}],"explain":{"en":"From Lesson 1: when you ask something personal, say why, right at the field.","ar":"من الدرس 1: حين تسأل عن شيء شخصي، وضّح السبب، عند الحقل مباشرة."},"speaker":"sara"},{"id":"S04","type":"tune","skill":"SK-P01-U01-04","part":"check","rules":["R19"],"value":{"en":"Skill check, marking required fields (NN/g): mark every required field, and label the few optional ones. A note at the top is skipped or forgotten.","ar":"اختبار مهارة، تمييز الحقول الإلزامية (NN/g): ميّز كل حقل إلزامي، وسمِّ القليل الاختياري. والملاحظة في الأعلى تُتخطّى أو تُنسى."},"ref":{"url":"https://www.nngroup.com/articles/required-fields/","quote":"People don’t read instructions at the top of forms."},"scenario":{"en":"After my trimming, every field is required except a new one: \"What should the coaches call him?\"","ar":"بعد ما حذفته، كل الحقول إلزامية إلا حقلًا جديدًا: «بماذا يناديه المدرّبون؟»"},"prompt":{"en":"Try each way of marking the form. Which one should ship?","ar":"جرّب كل طريقة لتمييز الحقول. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":""},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him?","ar":"بماذا يناديه المدرّبون؟"},"text":"","gap":"s"}]},"options":[{"id":"note","text":{"en":"A note at the top: \"All fields required except the last\"","ar":"ملاحظة في الأعلى: «كل الحقول إلزامية ما عدا الأخير»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"All fields are required except the last one.","ar":"كل الحقول إلزامية ما عدا الأخير."}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him?","ar":"بماذا يناديه المدرّبون؟"},"text":"","gap":"s"}]}},{"id":"both","text":{"en":"A star on each required field, \"(optional)\" on the last","ar":"نجمة على كل حقل إلزامي، و«(اختياري)» على الأخير"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"Child's full name *","ar":"اسم الطفل الكامل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Child's date of birth *","ar":"تاريخ ميلاد الطفل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number *","ar":"رقم موبايل وليّ الأمر *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions *","ar":"حساسية أو حالات طبية *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","gap":"s"}]}},{"id":"optonly","text":{"en":"Only \"(optional)\" on the last field","ar":"«(اختياري)» على الحقل الأخير فقط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":""},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","gap":"s"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-028","when":["note"],"feedback":{"en":"Samir may skip the note, or forget it by the last field. Put the answer on each field.","ar":"قد يتخطّى سمير الملاحظة، أو ينساها عند الحقل الأخير. ضع الإجابة عند كل حقل."}},{"id":"MC-P01-028","when":["optonly"],"feedback":{"en":"Nothing tells Samir that the other four must be filled in. If he doesn't notice the word at the end, he guesses. Star the required ones too.","ar":"لا شيء يخبر سمير أن الأربعة الأخرى يجب ملؤها. وإذا لم يلاحظ الكلمة في النهاية، فسيخمّن. ضع نجمة على الإلزامية أيضًا."}}],"explain":{"en":"From Lesson 2: a star on every required field, and \"(optional)\" on the ones people may skip.","ar":"من الدرس 2: نجمة على كل حقل إلزامي، و«(اختياري)» على الحقول التي يمكن تخطّيها."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U01-05","part":"check","rules":["R19"],"value":{"en":"Skill check, cognitive load in forms (NN/g): communicate requirements and set expectations upfront. The coaches only use the nickname if a parent gives one, so the check is wrong, not the label.","ar":"اختبار مهارة، العبء الذهني في النماذج (NN/g): وضّح المتطلبات وحدّد التوقعات مسبقًا. والمدرّبون يستخدمون اسم الدلع فقط إذا أعطاه الوالد، فالتحقق هو الخطأ، لا التسمية."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Communicate requirements and set expectations upfront."},"scenario":{"en":"In testing, Samir left the nickname empty and pressed Register. The coaches only use a nickname if a parent gives one.","ar":"في الاختبار، ترك سمير اسم الدلع فارغًا وضغط «سجّل». والمدرّبون يستخدمون اسم الدلع فقط إذا أعطاه الوالد."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","error":{"en":"This field is required.","ar":"هذا الحقل إلزامي."}},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]},"options":[{"id":"star","text":{"en":"Make the label required: add a star","ar":"اجعل التسمية إلزامية: أضف نجمة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"What should the coaches call him? *","ar":"بماذا يناديه المدرّبون؟ *"},"text":""},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it; the error explains what to do","ar":"أبقِه؛ فرسالة الخطأ توضّح ما يجب فعله"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","error":{"en":"This field is required.","ar":"هذا الحقل إلزامي."}},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"check","text":{"en":"Fix the check so an empty nickname goes through","ar":"أصلِح التحقق ليمرّ اسم الدلع الفارغ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":""},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"},{"kind":"small","color":"green","text":{"en":"Ziad is registered!","ar":"تمّ تسجيل زياد!"},"gap":"s"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-004","when":["star"],"feedback":{"en":"The label and the check now agree, but every parent must invent a nickname the academy doesn't need. Fix the check.","ar":"الآن تتّفق التسمية مع التحقق، لكن على كل والد أن يخترع اسم دلع لا تحتاجه الأكاديمية. أصلِح التحقق."}},{"id":"MC-P01-004","when":["keep"],"feedback":{"en":"The label said he could skip it, and the form punished him for trusting it. Make them agree.","ar":"قالت التسمية إنه يستطيع تخطّيه، ثم عاقبه النموذج لأنه صدّقها. اجعلهما يتّفقان."}}],"explain":{"en":"From Lesson 2: decide what the task needs, then make the label and the check say the same thing.","ar":"من الدرس 2: قرّر ما تحتاجه المهمة، ثم اجعل التسمية والتحقق يقولان الشيء نفسه."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U01-06","part":"check","rules":["R19"],"value":{"en":"Skill check, international sites (NN/g): separate first and last name fields are a prescription for confusion. One full-name field fits every family.","ar":"اختبار مهارة، المواقع الدولية (NN/g): الحقول المنفصلة للاسم الأول واسم العائلة وصفة للارتباك. وحقل واحد للاسم الكامل يناسب كل عائلة."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"Offering separate fields for first name and last name is a prescription for confusion."},"scenario":{"en":"The academy's developer wants to split the child's name so the system can sort by family name.","ar":"يريد مطوّر الأكاديمية تقسيم اسم الطفل ليتمكّن النظام من الترتيب حسب اسم العائلة."},"prompt":{"en":"Try each way of asking for Ziad's name. Which one should ship?","ar":"جرّب كل طريقة لطلب اسم زياد. أيّها يجب أن تُطلق؟"},"start":"split","options":[{"id":"one","text":{"en":"One field: \"Child's full name, as on his birth certificate\"","ar":"حقل واحد: «اسم الطفل الكامل، كما في شهادة الميلاد»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's full name, as on his birth certificate *","ar":"اسم الطفل الكامل، كما في شهادة الميلاد *"},"filled":true,"text":{"en":"Ziad Samir Abdelaziz Farid","ar":"زياد سمير عبد العزيز فريد"}}]}},{"id":"split","text":{"en":"Two fields: first name and last name","ar":"حقلان: الاسم الأول واسم العائلة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's first name *","ar":"الاسم الأول للطفل *"},"text":""},{"kind":"field","label":{"en":"Child's last name *","ar":"اسم عائلة الطفل *"},"text":"","gap":"s"}]}},{"id":"three","text":{"en":"Three fields: name, father's name, family name","ar":"ثلاثة حقول: الاسم، اسم الأب، اسم العائلة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's name *","ar":"اسم الطفل *"},"text":""},{"kind":"field","label":{"en":"Father's name *","ar":"اسم الأب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Family name *","ar":"اسم العائلة *"},"text":"","gap":"s"}]}}],"answer":["one"],"misconceptions":[{"id":"MC-P01-006","when":["split"],"feedback":{"en":"Samir has to decide where \"Samir Abdelaziz\" goes, and the next family's names won't fit two boxes either. One field.","ar":"على سمير أن يقرّر أين يكتب «سمير عبد العزيز»، وأسماء العائلة التالية لن تناسب خانتين أيضًا. حقل واحد."}},{"id":"MC-P01-006","when":["three"],"feedback":{"en":"This fits some families and fails others. Names don't share one structure; let each family type theirs.","ar":"هذا يناسب بعض العائلات ويفشل مع غيرها. الأسماء ليس لها بنية واحدة؛ فدع كل عائلة تكتب اسمها."}}],"explain":{"en":"From Lesson 3: one full-name field, typed as on the official document, fits every naming pattern.","ar":"من الدرس 3: حقل واحد للاسم الكامل، يُكتب كما في الوثيقة الرسمية، يناسب كل أنماط الأسماء."},"speaker":"sara"},{"id":"S07","type":"tune","skill":"SK-P01-U01-07","part":"check","rules":["R19"],"value":{"en":"Skill check, international sites (NN/g): allow phone numbers with a country code and a varying number of digits. ⁦+20 10 1234 5678⁩ is the same number as ⁦010 1234 5678⁩.","ar":"اختبار مهارة، المواقع الدولية (NN/g): اسمح بأرقام الهواتف مع رمز الدولة وبعدد أرقام متغيّر. والرقم ‎⁦+20 10 1234 5678⁩ هو نفسه ⁦010 1234 5678⁩."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"For phone numbers, allow for international numbers containing a varying number of digits and a country code."},"scenario":{"en":"In testing, Samir pasted his number from his contacts, with the country code. The form rejected it.","ar":"في الاختبار، لصق سمير رقمه من جهات الاتصال، مع رمز الدولة. فرفضه النموذج."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"filled":true,"text":"⁦+20 10 1234 5678⁩","error":{"en":"Use 11 digits starting with 0.","ar":"استخدم 11 رقمًا تبدأ بـ 0."}}]},"options":[{"id":"hint","text":{"en":"Add a hint: \"Start with 0, no country code\"","ar":"أضف تلميحًا: «ابدأ بـ 0، بدون رمز الدولة»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","hint":{"en":"Start with 0, no country code, no spaces.","ar":"ابدأ بـ 0، بدون رمز الدولة، بدون مسافات."}}]}},{"id":"accept","text":{"en":"Accept it with or without the country code and spaces","ar":"اقبله برمز الدولة أو بدونه، وبالمسافات"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"filled":true,"text":"⁦+20 10 1234 5678⁩"},{"kind":"small","color":"green","text":{"en":"✓ Saved","ar":"✓ تم الحفظ"},"gap":"xs"}]}},{"id":"picker","text":{"en":"Split it: a country box and an 11-digit box","ar":"قسّمه: خانة للدولة وخانة من 11 رقمًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","text":"⁦+20⁩"},{"kind":"field","tone":"bad","filled":true,"text":"⁦10 1234 5678⁩"}]},{"kind":"small","color":"red","text":{"en":"Use 11 digits starting with 0.","ar":"استخدم 11 رقمًا تبدأ بـ 0."},"gap":"xs"}]}}],"answer":["accept"],"misconceptions":[{"id":"MC-P01-007","when":["hint"],"feedback":{"en":"The number was right. Now Samir has to edit a pasted number by hand on his phone. Let the system tidy it.","ar":"الرقم كان صحيحًا. والآن على سمير أن يعدّل رقمًا ملصوقًا بيده على هاتفه. دع النظام يرتّبه."}},{"id":"MC-P01-007","when":["picker"],"feedback":{"en":"Splitting it still forces one exact shape, and his pasted number breaks again. Accept the number as people write it.","ar":"التقسيم ما زال يفرض شكلًا واحدًا محدّدًا، فيفشل رقمه الملصوق مرة أخرى. اقبل الرقم كما يكتبه الناس."}}],"explain":{"en":"From Lesson 3: accept the formats people actually use, country codes included, and tidy them in the system.","ar":"من الدرس 3: اقبل الصيغ التي يستخدمها الناس فعلًا، بما فيها رموز الدول، ورتّبها في النظام."},"speaker":"sara"}]}$uxg$::jsonb),
  ($uxg$P01-U02-L01$uxg$, $uxg$0b665d175904322987fd233ec4a757bcfc1913e993f18bf9fd0a956cb62595c6$uxg$, $uxg${"id":"P01-U02-L01","mode":"lesson","minutes":8,"title":{"en":"One, many, or a toggle","ar":"خيار واحد، أم عدة خيارات، أم Toggle؟"},"speaker":"nour","review_labels":{"MC-P01-015":{"en":"Don't preselect a guess for a personal answer","ar":"لا تحدّد تخمينًا مسبقًا لإجابة شخصية"},"MC-P01-018":{"en":"A toggle acts now; a checkbox waits for submit","ar":"الـ Toggle يعمل فورًا، والـ Checkbox ينتظر الإرسال"},"MC-P01-031":{"en":"Show a few options; don't hide them in a dropdown","ar":"اعرض الخيارات القليلة؛ لا تُخفِها في قائمة منسدلة"},"MC-P01-032":{"en":"One answer: radio buttons; several: checkboxes","ar":"إجابة واحدة: Radio buttons؛ عدة إجابات: Checkboxes"},"MC-P01-033":{"en":"A safe, common default saves a step","ar":"القيمة الافتراضية الشائعة والآمنة توفّر خطوة"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Ahmed's reminders","ar":"تذكيرات أحمد"},"body":{"en":"Ahmed, one of our patients, opened his profile in our clinic app to update his phone number. On the same screen, he switched visit reminders off. Then he closed the app without pressing Save.\n\nThe reminders kept coming.","ar":"فتح أحمد، أحد مرضانا، ملفه الشخصي في تطبيق عيادتنا لتحديث رقم هاتفه. وفي الشاشة نفسها، أطفأ تذكيرات المواعيد. ثم أغلق التطبيق دون أن يضغط «حفظ».\n\nوظلّت التذكيرات تصل."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-01","part":"try","rules":["R12"],"value":{"en":"Try first. Toggle switches (NN/g): toggles should give immediate results. A toggle inside a form with a Save button leaves people unsure whether it took effect; separate instant controls from ones that wait for a button.","ar":"جرّب أولًا. الـ Toggle switches (NN/g): يجب أن يعطي الـ Toggle نتيجة فورية. ووضعه داخل نموذج فيه زر «حفظ» يترك الناس غير متأكّدين هل نُفّذ التغيير؛ فافصل العناصر الفورية عن تلك التي تنتظر زرًا."},"ref":{"url":"https://www.nngroup.com/articles/toggle-switch-guidelines/","quote":"Separate controls that produce instant results from those that require clicking a command button."},"scenario":{"en":"Our profile screen needs its Save button for the phone number. My team wants to keep the reminders setting on the same screen.","ar":"شاشة الملف الشخصي عندنا تحتاج زر «حفظ» من أجل رقم الهاتف. ويريد فريقي إبقاء إعداد التذكيرات في الشاشة نفسها."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]},"options":[{"id":"note","text":{"en":"Keep the toggle; add \"Press Save to apply changes\"","ar":"أبقِ الـ Toggle؛ وأضف «اضغط حفظ لتطبيق التغييرات»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"small","text":{"en":"Press Save to apply changes.","ar":"اضغط «حفظ» لتطبيق التغييرات."},"gap":"s"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"s"}]}},{"id":"check","text":{"en":"Use a checkbox that's saved with the form","ar":"استخدم Checkbox يُحفظ مع النموذج"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"check","selected":true,"text":{"en":"Send me visit reminders","ar":"أرسل لي تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it as it is; people know to press Save","ar":"أبقِه كما هو؛ فالناس يعرفون أن يضغطوا «حفظ»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-018","when":["keep"],"feedback":{"en":"A toggle looks like a light switch, so Ahmed expected it to work the moment he flipped it. On a screen that waits for Save, it breaks that promise.","ar":"الـ Toggle يشبه مفتاح الإضاءة، فتوقّع أحمد أن يعمل لحظة تحريكه. وفي شاشة تنتظر «حفظ»، يُخلف هذا الوعد."}},{"id":"MC-P01-018","when":["note"],"feedback":{"en":"The note fights the control. The toggle still says \"done\"; few people read the line under it. Use a control that waits, like a checkbox.","ar":"الملاحظة تعارض العنصر. فالـ Toggle ما زال يقول «تمّ»؛ وقليلون يقرؤون السطر تحته. استخدم عنصرًا ينتظر، مثل الـ Checkbox."}}],"hints":[{"en":"When does the reminders change happen: at once, or when Ahmed presses Save?","ar":"متى يحدث تغيير التذكيرات: فورًا، أم عندما يضغط أحمد «حفظ»؟"},{"en":"A toggle promises \"right now\". Does this screen keep that promise?","ar":"الـ Toggle يعد بالتنفيذ «الآن». هل تفي هذه الشاشة بهذا الوعد؟"}],"correct":{"en":"In a form that waits for Save, use a checkbox.","ar":"في نموذج ينتظر «حفظ»، استخدم Checkbox."},"explain":{"en":"A checkbox doesn't promise instant action, so it fits a form that applies changes on Save. Keep toggles for settings that work the moment you flip them.","ar":"الـ Checkbox لا يَعِد بتنفيذ فوري، لذلك يناسب نموذجًا يطبّق التغييرات عند «حفظ». واحتفظ بالـ Toggle للإعدادات التي تعمل لحظة تحريكها."},"speaker":"nour"},{"id":"S03","type":"card","part":"concept","icons":["form","list","clock","idea"],"title":{"en":"Each control makes a promise","ar":"كل عنصر تحكّم يَعِد بشيء"},"body":{"en":"People read a control's shape before its label. Pick the one whose promise matches what happens.\n\n- **Radio buttons:** pick exactly one. All the choices are visible.\n- **Checkboxes:** pick any number, including none. Each box works on its own.\n- **Toggle:** on or off, right now. Use it for settings that apply instantly.\n- **Dropdown:** hides the choices behind a tap. With only a few options, show them as radio buttons instead.\n- **A default choice** saves a step when one answer is common and safe. Don't preselect a guess about someone's personal life.","ar":"يقرأ الناس شكل العنصر قبل تسميته. فاختر العنصر الذي يطابق وعدُه ما يحدث فعلًا.\n\n- **الـ Radio buttons:** اختر واحدًا فقط. وكل الخيارات ظاهرة.\n- **الـ Checkboxes:** اختر أي عدد، حتى لا شيء. وكل مربع يعمل وحده.\n- **الـ Toggle:** تشغيل أو إيقاف، الآن. استخدمه للإعدادات التي تُطبَّق فورًا.\n- **القائمة المنسدلة (Dropdown):** تُخفي الخيارات خلف ضغطة. ومع خيارات قليلة، اعرضها كـ Radio buttons بدلًا منها.\n- **الخيار الافتراضي** يوفّر خطوة حين تكون إجابة واحدة شائعة وآمنة. ولا تحدّد مسبقًا تخمينًا عن حياة شخص الخاصة."}},{"id":"S04","type":"tune","skill":"SK-P01-U02-02","part":"guided","rules":["R06","R15"],"value":{"en":"Dropdown lists (NN/g): when a handful of options fits on screen, a dropdown adds more friction than value. Radio buttons show every choice and take one tap.","ar":"القوائم المنسدلة (NN/g): حين تتّسع الشاشة لعدد قليل من الخيارات، تضيف القائمة المنسدلة عناءً أكثر من فائدتها. والـ Radio buttons تعرض كل خيار وتحتاج ضغطة واحدة."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"When a handful of options can comfortably fit on screen, a dropdown adds more friction than real value."},"scenario":{"en":"Ahmed is booking a visit with us. It can be in person or a video call, never both.","ar":"يحجز أحمد موعدًا عندنا. ويمكن أن يكون حضوريًا أو مكالمة فيديو، ولا يكون الاثنين معًا."},"prompt":{"en":"Try each control for the visit type. Which one should ship?","ar":"جرّب كل عنصر لنوع الزيارة. أيّها يجب أن يُطلق؟"},"start":"dropdown","options":[{"id":"dropdown","text":{"en":"A dropdown","ar":"قائمة منسدلة"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Visit type","ar":"نوع الزيارة"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"checks","text":{"en":"Two checkboxes","ar":"مربّعا Checkbox"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit type","ar":"نوع الزيارة"}},{"kind":"check","text":{"en":"In person","ar":"حضوري"},"gap":"xs"},{"kind":"check","text":{"en":"Video call","ar":"مكالمة فيديو"},"gap":"xs"}]}},{"id":"radios","text":{"en":"Two radio buttons","ar":"زرّا Radio"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit type","ar":"نوع الزيارة"}},{"kind":"radio","text":{"en":"In person","ar":"حضوري"},"gap":"xs"},{"kind":"radio","text":{"en":"Video call","ar":"مكالمة فيديو"},"gap":"xs"}]}}],"answer":["radios"],"misconceptions":[{"id":"MC-P01-031","when":["dropdown"],"feedback":{"en":"Ahmed has to open it to find out there are only two choices, then tap again. Two options fit on screen; show them.","ar":"على أحمد أن يفتحها ليكتشف أن هناك خيارين فقط، ثم يضغط مرة أخرى. والخياران يتّسعان على الشاشة؛ فاعرضهما."}},{"id":"MC-P01-032","when":["checks"],"feedback":{"en":"Checkboxes say \"pick any\", so Ahmed could tick both, or neither. A visit is one or the other: that's a radio choice.","ar":"الـ Checkboxes تقول «اختر أيًّا منها»، فقد يحدّد أحمد الاثنين، أو لا شيء. والزيارة إما هذا أو ذاك: وهذا اختيار Radio."}}],"hints":[{"en":"Can a visit be in person and a video call at the same time?","ar":"هل يمكن أن تكون الزيارة حضورية ومكالمة فيديو في الوقت نفسه؟"},{"en":"With just two choices, should Ahmed have to tap to see them?","ar":"مع خيارين فقط، هل يجب أن يضغط أحمد لكي يراهما؟"}],"correct":{"en":"One of a few: radio buttons.","ar":"واحد من خيارات قليلة: Radio buttons."},"explain":{"en":"Radio buttons show every choice at once and allow exactly one. For two to about five options, they're the fastest and clearest.","ar":"الـ Radio buttons تعرض كل الخيارات مرة واحدة وتسمح باختيار واحد فقط. ومن خيارين إلى نحو خمسة، هي الأسرع والأوضح."},"speaker":"nour"},{"id":"S05","type":"tune","skill":"SK-P01-U02-02","part":"guided","rules":["R06","R15"],"value":{"en":"Checkboxes (NN/g): a checkbox list lets people select one, several, all, or none. Allergies are any number, so radio buttons or a single-select dropdown lose answers.","ar":"الـ Checkboxes (NN/g): قائمة الـ Checkboxes تتيح اختيار واحد أو عدة أو الكل أو لا شيء. والحساسية قد تكون أي عدد، فالـ Radio buttons أو القائمة المنسدلة ذات الاختيار الواحد تُضيّع إجابات."},"ref":{"url":"https://www.nngroup.com/articles/checkboxes-design-guidelines/","quote":"A checkbox list allows users the unique ability to select one, several, all, or no items from a list."},"scenario":{"en":"Ahmed is allergic to penicillin and to nuts. Our health form asks about common allergies.","ar":"لدى أحمد حساسية من البنسلين ومن المكسّرات. ونموذج الصحة عندنا يسأل عن أنواع الحساسية الشائعة."},"prompt":{"en":"Try each control. Which one lets Ahmed tell the doctor everything?","ar":"جرّب كل عنصر. أيّها يتيح لأحمد أن يخبر الطبيب بكل شيء؟"},"start":"radio","options":[{"id":"radio","text":{"en":"Radio buttons","ar":"Radio buttons"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Allergies","ar":"الحساسية"}},{"kind":"radio","selected":true,"text":{"en":"Penicillin","ar":"البنسلين"},"gap":"xs"},{"kind":"radio","text":{"en":"Nuts","ar":"المكسّرات"},"gap":"xs"},{"kind":"radio","text":{"en":"Latex","ar":"اللاتكس"},"gap":"xs"}]}},{"id":"check","text":{"en":"Checkboxes","ar":"Checkboxes"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Allergies (tick all that apply)","ar":"الحساسية (حدّد كل ما ينطبق)"}},{"kind":"check","selected":true,"text":{"en":"Penicillin","ar":"البنسلين"},"gap":"xs"},{"kind":"check","selected":true,"text":{"en":"Nuts","ar":"المكسّرات"},"gap":"xs"},{"kind":"check","text":{"en":"Latex","ar":"اللاتكس"},"gap":"xs"}]}},{"id":"select","text":{"en":"A dropdown","ar":"قائمة منسدلة"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Allergies","ar":"الحساسية"},"filled":true,"text":{"en":"Penicillin","ar":"البنسلين"}}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-032","when":["radio","select"],"feedback":{"en":"This control allows one answer. When Ahmed picks nuts, penicillin disappears, and the doctor never learns about it.","ar":"هذا العنصر يسمح بإجابة واحدة. فحين يختار أحمد المكسّرات، يختفي البنسلين، ولا يعرف الطبيب به أبدًا."}}],"hints":[{"en":"How many allergies does Ahmed have?","ar":"كم حساسية لدى أحمد؟"},{"en":"Which control lets him pick more than one answer?","ar":"أي عنصر يسمح له باختيار أكثر من إجابة؟"}],"correct":{"en":"Any number of answers: checkboxes.","ar":"أي عدد من الإجابات: Checkboxes."},"explain":{"en":"Each checkbox works on its own, so Ahmed can tick both allergies. The label \"tick all that apply\" removes any doubt.","ar":"كل Checkbox يعمل وحده، فيستطيع أحمد تحديد نوعي الحساسية. وعبارة «حدّد كل ما ينطبق» تُزيل أي شك."},"speaker":"nour"},{"id":"S06","type":"tune","skill":"SK-P01-U02-03","part":"guided","rules":["R06","R15"],"value":{"en":"Radio-button defaults (NN/g): a presumptuous or alienating choice is the most valid reason not to preselect. A guessed marital status is presumptuous, wrong for many, and easy to leave unchanged.","ar":"الخيار الافتراضي في الـ Radio buttons (NN/g): الاختيار المتسرّع في الافتراض أو المنفّر هو أقوى سبب لعدم التحديد المسبق. والحالة الاجتماعية المخمّنة افتراض متسرّع، وخاطئة لكثيرين، وسهل أن تُترك دون تغيير."},"ref":{"url":"https://www.nngroup.com/articles/radio-buttons-default-selection/","quote":"This is probably the most valid reason for not selecting a radio button by default."},"scenario":{"en":"Our doctor needs Ahmed's marital status for some treatments. Most of our patients are married, so the form preselects \"Married\".","ar":"يحتاج طبيبنا الحالة الاجتماعية لأحمد لبعض العلاجات. وأغلب مرضانا متزوّجون، فيحدّد النموذج «متزوّج» مسبقًا."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Marital status","ar":"الحالة الاجتماعية"}},{"kind":"radio","selected":true,"text":{"en":"Married","ar":"متزوّج"},"gap":"xs"},{"kind":"radio","text":{"en":"Single","ar":"أعزب"},"gap":"xs"},{"kind":"radio","text":{"en":"Divorced","ar":"مطلّق"},"gap":"xs"},{"kind":"radio","text":{"en":"Widowed","ar":"أرمل"},"gap":"xs"}]},"options":[{"id":"none","text":{"en":"No option selected; he chooses","ar":"بلا خيار محدّد؛ وهو يختار"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Marital status","ar":"الحالة الاجتماعية"}},{"kind":"radio","text":{"en":"Married","ar":"متزوّج"},"gap":"xs"},{"kind":"radio","text":{"en":"Single","ar":"أعزب"},"gap":"xs"},{"kind":"radio","text":{"en":"Divorced","ar":"مطلّق"},"gap":"xs"},{"kind":"radio","text":{"en":"Widowed","ar":"أرمل"},"gap":"xs"}]}},{"id":"keep","text":{"en":"Keep \"Married\" preselected; it's the most common","ar":"أبقِ «متزوّج» محدّدًا مسبقًا؛ فهو الأكثر شيوعًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Marital status","ar":"الحالة الاجتماعية"}},{"kind":"radio","selected":true,"text":{"en":"Married","ar":"متزوّج"},"gap":"xs"},{"kind":"radio","text":{"en":"Single","ar":"أعزب"},"gap":"xs"},{"kind":"radio","text":{"en":"Divorced","ar":"مطلّق"},"gap":"xs"},{"kind":"radio","text":{"en":"Widowed","ar":"أرمل"},"gap":"xs"}]}},{"id":"hide","text":{"en":"Move it into a dropdown, with \"Married\" showing","ar":"انقله إلى قائمة منسدلة، تظهر فيها «متزوّج»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Marital status","ar":"الحالة الاجتماعية"},"filled":true,"text":{"en":"Married","ar":"متزوّج"}}]}}],"answer":["none"],"misconceptions":[{"id":"MC-P01-015","when":["keep"],"feedback":{"en":"For a single patient in a hurry, \"Married\" stays and the doctor's record is wrong. A personal answer shouldn't start as a guess.","ar":"إذا كان المريض أعزب ومستعجلًا، فستبقى «متزوّج» ويصبح سجل الطبيب خاطئًا. والإجابة الشخصية لا يجب أن تبدأ بتخمين."}},{"id":"MC-P01-015","when":["hide"],"feedback":{"en":"Same guess, now harder to see: a filled dropdown looks already answered. People rarely open it to check.","ar":"التخمين نفسه، لكنه الآن أصعب في الرؤية: القائمة المنسدلة الممتلئة تبدو مُجابة بالفعل. ونادرًا ما يفتحها الناس للتحقّق."}}],"hints":[{"en":"Whose answer is this: the clinic's guess, or Ahmed's?","ar":"إجابة من هذه: تخمين العيادة، أم إجابة أحمد؟"},{"en":"If he skims past a wrong preselected answer, what does the doctor see?","ar":"إذا مرّ أحمد سريعًا على إجابة محدّدة مسبقًا وخاطئة، ماذا سيرى الطبيب؟"}],"correct":{"en":"Let him choose a personal answer.","ar":"دعه يختار الإجابة الشخصية."},"explain":{"en":"A default is a suggestion, and people often keep suggestions. For something personal, no suggestion is the respectful and accurate choice.","ar":"الخيار الافتراضي اقتراح، والناس كثيرًا ما يُبقون الاقتراحات. وفي الأمور الشخصية، عدم الاقتراح هو الخيار المحترم والدقيق."},"speaker":"nour"},{"id":"S07","type":"compare","skill":"SK-P01-U02-03","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S06: defaults aren't bad in general. Radio-button defaults (NN/g): select one by default in most cases. A common, harmless setting like reminder timing should start on the usual choice.","ar":"مقارنة مع الخطوة 6: الخيار الافتراضي ليس سيئًا بشكل عام. الخيار الافتراضي في الـ Radio buttons (NN/g): حدّد خيارًا افتراضيًا في أغلب الحالات. والإعداد الشائع غير الضار، مثل توقيت التذكير، يجب أن يبدأ بالاختيار المعتاد."},"ref":{"url":"https://www.nngroup.com/articles/radio-buttons-default-selection/","quote":"Select a single radio button by default in most cases."},"scenario":{"en":"Ahmed turns reminders on. Almost everyone wants theirs one day before; either choice is easy to change later.","ar":"يشغّل أحمد التذكيرات. وأغلب الناس يريدون التذكير قبل يوم؛ وأي اختيار سهل التغيير لاحقًا."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Remind me","ar":"ذكّرني"}},{"kind":"radio","text":{"en":"1 day before","ar":"قبل الموعد بيوم"},"gap":"xs"},{"kind":"radio","text":{"en":"2 hours before","ar":"قبل الموعد بساعتين"},"gap":"xs"},{"kind":"radio","text":{"en":"Both","ar":"الاثنان"},"gap":"xs"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Remind me","ar":"ذكّرني"}},{"kind":"radio","selected":true,"text":{"en":"1 day before","ar":"قبل الموعد بيوم"},"gap":"xs"},{"kind":"radio","text":{"en":"2 hours before","ar":"قبل الموعد بساعتين"},"gap":"xs"},{"kind":"radio","text":{"en":"Both","ar":"الاثنان"},"gap":"xs"}]}},"answer":"b","reason":{"prompt":{"en":"Why is a default right here, but wrong for marital status?","ar":"لماذا يصحّ الخيار الافتراضي هنا، ويخطئ في الحالة الاجتماعية؟"},"options":[{"id":"safe","text":{"en":"It's the usual choice, and leaving it costs nothing","ar":"إنه الاختيار المعتاد، وتركه لا يكلّف شيئًا"}},{"id":"always","text":{"en":"Radio buttons always need a default","ar":"الـ Radio buttons تحتاج دائمًا خيارًا افتراضيًا"}},{"id":"short","text":{"en":"The list is shorter","ar":"القائمة أقصر"}}],"answer":["safe"],"misconceptions":[{"id":"MC-P01-033","when":["always","short"],"feedback":{"en":"Length and habit aren't the reason. It's about the cost of a wrong default: here it's a slightly early reminder; there it's a wrong medical record.","ar":"الطول والعادة ليسا السبب. السبب هو كلفة الخيار الافتراضي الخاطئ: هنا تذكير أبكر قليلًا؛ وهناك سجل طبي خاطئ."}}]},"misconceptions":[{"id":"MC-P01-033","when":["a"],"feedback":{"en":"A makes everyone choose, though nearly all pick \"1 day before\". With a safe, common answer, start there.","ar":"A تجعل الجميع يختارون، مع أن أغلبهم يختار «قبل الموعد بيوم». ومع إجابة شائعة وآمنة، ابدأ بها."}}],"hints":[{"en":"Is this a personal answer, or a common and harmless setting?","ar":"هل هذه إجابة شخصية، أم إعداد شائع ولا ضرر منه؟"},{"en":"If almost everyone picks the same one and it's easy to change, does it need an empty start?","ar":"إذا اختار الجميع تقريبًا الخيار نفسه وكان تغييره سهلًا، فهل يحتاج أن يبدأ فارغًا؟"}],"correct":{"en":"Common and harmless: preselect it.","ar":"شائع وغير ضار: حدّده مسبقًا."},"explain":{"en":"Ask what happens if someone leaves the default. If the answer is \"nothing bad\", a default saves a step. If it's a wrong record, let them choose.","ar":"اسأل ماذا يحدث إذا ترك أحد الخيار الافتراضي. إذا كانت الإجابة «لا شيء سيئ»، فالخيار الافتراضي يوفّر خطوة. وإذا كانت سجلًا خاطئًا، فدعه يختار."},"speaker":"nour"},{"id":"S08","type":"tune","skill":"SK-P01-U02-01","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Toggle switches (NN/g): a toggle inside a form that waits for a button leaves people unsure whether their choice took effect. Tamer's checkout only applies choices on Place order.","ar":"حالة جديدة. الـ Toggle switches (NN/g): الـ Toggle داخل نموذج ينتظر زرًا يترك الناس غير متأكّدين هل نُفّذ اختيارهم. وصفحة الدفع عند تامر تطبّق الاختيارات فقط عند «أكّد الطلب»."},"ref":{"url":"https://www.nngroup.com/articles/toggle-switch-guidelines/","quote":"This scenario confuses users because they can’t be sure whether their toggle choice will take immediate effect."},"scenario":{"en":"In our lunch app, Tamer's checkout has a \"Leave it at the door\" toggle above Place order. Nothing is sent to the driver until he places the order.","ar":"في تطبيق الغداء عندنا، فيه Toggle «اتركه عند الباب» فوق «أكّد الطلب» في صفحة الدفع عند تامر. ولا يُرسل شيء للسائق حتى يؤكّد الطلب."},"prompt":{"en":"Try each control. Which one should ship?","ar":"جرّب كل عنصر. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"toggle","text":{"en":"Leave it at the door","ar":"اتركه عند الباب"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"select","text":{"en":"A dropdown: Yes / No","ar":"قائمة منسدلة: نعم / لا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"select","label":{"en":"Leave it at the door?","ar":"تتركه عند الباب؟"},"text":{"en":"Select…","ar":"اختر…"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep the toggle","ar":"أبقِ الـ Toggle"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"toggle","text":{"en":"Leave it at the door","ar":"اتركه عند الباب"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"check","text":{"en":"A checkbox, sent with the order","ar":"Checkbox يُرسل مع الطلب"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"check","text":{"en":"Leave it at the door","ar":"اتركه عند الباب"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-018","when":["keep"],"feedback":{"en":"Flipping the toggle looks like it's done. Tamer might flip it, change his mind about ordering, and wonder whether the driver was told.","ar":"تحريك الـ Toggle يبدو كأن الأمر تمّ. وقد يحرّكه تامر، ثم يغيّر رأيه في الطلب، ويتساءل هل أُبلغ السائق."}},{"id":"MC-P01-031","when":["select"],"feedback":{"en":"A yes/no hidden in a dropdown takes two taps and hides the choice. One checkbox says it in one tap.","ar":"سؤال نعم/لا مخفي في قائمة منسدلة يحتاج ضغطتين ويُخفي الاختيار. وCheckbox واحد يقولها بضغطة واحدة."}}],"hints":[{"en":"When does the driver get this choice: when Tamer flips it, or when he places the order?","ar":"متى يصل هذا الاختيار إلى السائق: عندما يغيّره تامر، أم عندما يرسل الطلب؟"},{"en":"Which control says \"this is saved with the form\"?","ar":"أي عنصر يقول «هذا يُحفظ مع النموذج»؟"}],"correct":{"en":"Part of the order: a checkbox.","ar":"جزء من الطلب: Checkbox."},"explain":{"en":"The choice only matters once he places the order, so it belongs with the order. A checkbox waits for the button, like the rest of the form.","ar":"الاختيار لا يهم إلا عند تأكيد الطلب، فمكانه مع الطلب. والـ Checkbox ينتظر الزر، مثل باقي النموذج."}},{"id":"S09","type":"card","part":"recap","icons":["form","list","clock","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Toggle or checkbox:** used checkboxes in forms that wait for Save or a submit button.\n- **One of a few:** showed two choices as radio buttons, not a dropdown.\n- **Any number:** used checkboxes so every allergy reached the doctor.\n- **Personal answers:** left them unselected.\n- **Safe, common choices:** preselected them to save a step.\n\nNext lesson: typing, picking, and the controls in between.","ar":"- **Toggle أم Checkbox:** استخدمت الـ Checkboxes في النماذج التي تنتظر «حفظ» أو زر إرسال.\n- **واحد من خيارات قليلة:** عرضت خيارين كـ Radio buttons، لا كقائمة منسدلة.\n- **أي عدد:** استخدمت الـ Checkboxes لتصل كل أنواع الحساسية إلى الطبيب.\n- **الإجابات الشخصية:** تركتها دون تحديد.\n- **الاختيارات الشائعة والآمنة:** حدّدتها مسبقًا لتوفير خطوة.\n\nالدرس التالي: الكتابة والاختيار والعناصر بينهما."}}]}$uxg$::jsonb),
  ($uxg$P01-U02-L02$uxg$, $uxg$1c58efc6ee9eb14fb4b4dcdb5fb1c4e910dc9adbf8313eb470ec11a28d3a62c3$uxg$, $uxg${"id":"P01-U02-L02","mode":"lesson","minutes":8,"title":{"en":"Type, pick, or step","ar":"تكتب، أم تختار، أم تزيد وتنقص؟"},"speaker":"nour","review_labels":{"MC-P01-012":{"en":"Let people type what they know by heart","ar":"دع الناس يكتبون ما يحفظونه"},"MC-P01-013":{"en":"Let people pick what only the system knows","ar":"دع الناس يختارون ما لا يعرفه إلا النظام"},"MC-P01-021":{"en":"IDs and codes are text made of digits","ar":"الأرقام التعريفية والرموز نص مكوّن من أرقام"},"MC-P01-022":{"en":"Sliders are for rough values","ar":"الـ Slider للقيم التقريبية"},"MC-P01-023":{"en":"Small counts near a default: a stepper","ar":"الأعداد الصغيرة القريبة من قيمة شائعة: Stepper"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Ahmed's date of birth","ar":"تاريخ ميلاد أحمد"},"body":{"en":"We ask for Ahmed's date of birth. Tapping the field opens a calendar on today's month, October 2026.\n\nAhmed was born in March 1991.","ar":"نطلب تاريخ ميلاد أحمد. والضغط على الحقل يفتح تقويمًا على الشهر الحالي، أكتوبر 2026.\n\nوأحمد مولود في مارس 1991."},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"text","text":"‹"},{"kind":"text","weight":"bold","text":{"en":"October 2026","ar":"أكتوبر 2026"}},{"kind":"text","text":"›"}]},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":"1"},{"kind":"chip","tone":"off","text":"2"},{"kind":"chip","tone":"off","text":"3"},{"kind":"chip","tone":"off","text":"4"},{"kind":"chip","tone":"off","text":"5"},{"kind":"chip","tone":"off","text":"6"},{"kind":"chip","tone":"off","text":"7"}]}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-04","part":"try","rules":["R12"],"value":{"en":"Try first. Date input (NN/g): calendar pickers suit dates close to now, within a year. Split dropdowns for day, month and year take many unnecessary steps. Let people type a date they know.","ar":"جرّب أولًا. إدخال التاريخ (NN/g): التقويم يناسب التواريخ القريبة من الآن، خلال سنة. والقوائم المنسدلة المنفصلة لليوم والشهر والسنة تحتاج خطوات كثيرة غير ضرورية. دع الناس يكتبون تاريخًا يعرفونه."},"ref":{"url":"https://www.nngroup.com/articles/date-input/","quote":"Calendar pickers should be used for events close to the present time — within less than a year."},"prompt":{"en":"Try each way of asking for his date of birth. Which one should ship?","ar":"جرّب كل طريقة لطلب تاريخ ميلاده. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"text","text":"‹"},{"kind":"text","weight":"bold","text":{"en":"October 2026","ar":"أكتوبر 2026"}},{"kind":"text","text":"›"}]},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":"1"},{"kind":"chip","tone":"off","text":"2"},{"kind":"chip","tone":"off","text":"3"},{"kind":"chip","tone":"off","text":"4"},{"kind":"chip","tone":"off","text":"5"},{"kind":"chip","tone":"off","text":"6"},{"kind":"chip","tone":"off","text":"7"}]}]},"options":[{"id":"dropdowns","text":{"en":"Three dropdowns: day, month, year","ar":"ثلاث قوائم منسدلة: اليوم، الشهر، السنة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"select","label":{"en":"Day","ar":"اليوم"},"text":"1"},{"kind":"select","label":{"en":"Month","ar":"الشهر"},"text":{"en":"Jan","ar":"يناير"}},{"kind":"select","label":{"en":"Year","ar":"السنة"},"text":"2026"}]},{"kind":"small","text":{"en":"Year list: 2026 down to 1926","ar":"قائمة السنوات: من 2026 حتى 1926"},"gap":"xs"}]}},{"id":"typed","text":{"en":"Three short fields he types into","ar":"ثلاثة حقول قصيرة يكتب فيها"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","label":{"en":"Day","ar":"اليوم"},"filled":true,"text":"14"},{"kind":"field","label":{"en":"Month","ar":"الشهر"},"filled":true,"text":"3"},{"kind":"field","label":{"en":"Year","ar":"السنة"},"filled":true,"text":"1991"}]}]}},{"id":"year","text":{"en":"Keep the calendar; add a year dropdown on top","ar":"أبقِ التقويم؛ وأضف قائمة منسدلة للسنة فوقه"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"select","text":{"en":"October","ar":"أكتوبر"}},{"kind":"select","text":"2026"}]},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":"1"},{"kind":"chip","tone":"off","text":"2"},{"kind":"chip","tone":"off","text":"3"},{"kind":"chip","tone":"off","text":"4"},{"kind":"chip","tone":"off","text":"5"},{"kind":"chip","tone":"off","text":"6"},{"kind":"chip","tone":"off","text":"7"}]}]}}],"answer":["typed"],"misconceptions":[{"id":"MC-P01-012","when":["dropdowns"],"feedback":{"en":"Each dropdown is a tap, a scroll and another tap, and the year list is a hundred items long. He knows the answer; let him type it.","ar":"كل قائمة منسدلة ضغطة وتمرير وضغطة أخرى، وقائمة السنوات طولها مئة عنصر. وهو يعرف الإجابة؛ فدعه يكتبها."}},{"id":"MC-P01-012","when":["year"],"feedback":{"en":"Better than going back 427 months, but he still scrolls 35 years, picks a month, then finds the day. Three typed numbers are faster.","ar":"أفضل من الرجوع 427 شهرًا، لكنه ما زال يمرّر 35 سنة، ويختار الشهر، ثم يبحث عن اليوم. وثلاثة أرقام مكتوبة أسرع."}}],"hints":[{"en":"Where does Ahmed's date of birth live: in the system, or in his head?","ar":"أين يوجد تاريخ ميلاد أحمد: في النظام، أم في ذهنه؟"},{"en":"How many taps does each version need to reach March 1991?","ar":"كم ضغطة تحتاج كل نسخة للوصول إلى مارس 1991؟"}],"correct":{"en":"He knows it by heart: let him type it.","ar":"يحفظه عن ظهر قلب: فدعه يكتبه."},"explain":{"en":"Typing 14, 3, 1991 takes seconds. Labelled Day, Month and Year fields remove any doubt about the order. Calendars are for dates people don't know yet.","ar":"كتابة 14 و3 و1991 تأخذ ثواني. والحقول المسمّاة اليوم والشهر والسنة تُزيل أي شك في الترتيب. والتقويم للتواريخ التي لا يعرفها الناس بعد."}},{"id":"S03","type":"card","part":"concept","icons":["form","clock","list","idea"],"title":{"en":"Who knows the answer?","ar":"من يعرف الإجابة؟"},"body":{"en":"Choose the control by asking where the answer lives.\n\n- **In the person's head:** let them type. A date of birth fits three labelled fields.\n- **Only in the system:** let them pick, like free appointment days. Gray out and disable what isn't available.\n- **A small count with a usual value:** a **stepper** (− and +), starting at that value.\n- **Exact numbers:** a text field. A **slider** is for exploring a range, and pairs well with fields for exact values.\n- **IDs and codes:** a text field that opens the number pad. They're labels made of digits, not amounts.","ar":"اختر العنصر بسؤال: أين توجد الإجابة؟\n\n- **في رأس الشخص:** دعه يكتب. وتاريخ الميلاد يناسبه ثلاثة حقول مسمّاة.\n- **في النظام فقط:** دعه يختار، مثل أيام المواعيد المتاحة. واجعل غير المتاح رماديًا ومعطّلًا.\n- **عدد صغير له قيمة معتادة:** **Stepper** (− و+)، يبدأ من تلك القيمة.\n- **الأرقام الدقيقة:** حقل نص. والـ **Slider** لاستكشاف مدى، ويعمل جيدًا مع حقول للقيم الدقيقة.\n- **الأرقام التعريفية والرموز:** حقل نص يفتح لوحة الأرقام. فهي تسميات مكوّنة من أرقام، لا كميات."}},{"id":"S04","type":"tune","skill":"SK-P01-U02-05","part":"guided","rules":["R06","R15"],"value":{"en":"Date input (NN/g): make choices clear by disabling and graying out options that aren't available. Only the clinic knows which days the doctor works.","ar":"إدخال التاريخ (NN/g): وضّح الاختيارات بتعطيل الخيارات غير المتاحة وجعلها رمادية. والعيادة وحدها تعرف الأيام التي يعمل فيها الطبيب."},"ref":{"url":"https://www.nngroup.com/articles/date-input/","quote":"Make the choices clear by disabling and graying out options that are not available or are illogical pairs."},"scenario":{"en":"Ahmed needs a visit next week. Dr. Hany, one of our doctors, sees patients only on Sundays and Wednesdays.","ar":"يحتاج أحمد موعدًا الأسبوع القادم. ود. هاني، أحد أطبائنا، يستقبل المرضى يومي الأحد والأربعاء فقط."},"prompt":{"en":"Try each way of picking the day. Which one should ship?","ar":"جرّب كل طريقة لاختيار اليوم. أيّها يجب أن تُطلق؟"},"start":"field","options":[{"id":"field","text":{"en":"A date field he types into","ar":"حقل تاريخ يكتب فيه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Visit date","ar":"تاريخ الزيارة"},"filled":true,"text":{"en":"Tue 3 November","ar":"الثلاثاء 3 نوفمبر"}},{"kind":"small","color":"red","text":{"en":"Dr. Hany isn't available on this day.","ar":"د. هاني غير متاح في هذا اليوم."},"gap":"xs"}]}},{"id":"all","text":{"en":"A calendar with every day open; check after he picks","ar":"تقويم كل أيامه مفتوحة؛ والتحقق بعد أن يختار"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"November 2026","ar":"نوفمبر 2026"}},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","text":{"en":"Sun 1","ar":"أحد 1"}},{"kind":"chip","text":{"en":"Mon 2","ar":"اثنين 2"}},{"kind":"chip","tone":"dark","text":{"en":"Tue 3","ar":"ثلاثاء 3"}},{"kind":"chip","text":{"en":"Wed 4","ar":"أربعاء 4"}}]},{"kind":"small","color":"red","text":{"en":"Dr. Hany isn't available on this day.","ar":"د. هاني غير متاح في هذا اليوم."},"gap":"s"}]}},{"id":"blocked","text":{"en":"A calendar where only Sundays and Wednesdays can be picked","ar":"تقويم لا يمكن فيه اختيار إلا الأحد والأربعاء"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"November 2026","ar":"نوفمبر 2026"}},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","text":{"en":"Sun 1","ar":"أحد 1"}},{"kind":"chip","tone":"off","text":{"en":"Mon 2","ar":"اثنين 2"}},{"kind":"chip","tone":"off","text":{"en":"Tue 3","ar":"ثلاثاء 3"}},{"kind":"chip","text":{"en":"Wed 4","ar":"أربعاء 4"}}]},{"kind":"small","text":{"en":"Dr. Hany sees patients on Sundays and Wednesdays.","ar":"يستقبل د. هاني المرضى يومي الأحد والأربعاء."},"gap":"s"}]}}],"answer":["blocked"],"misconceptions":[{"id":"MC-P01-013","when":["field","all"],"feedback":{"en":"Ahmed can't know the doctor's days, so he guesses and gets an error. Show him what's possible before he picks.","ar":"لا يستطيع أحمد معرفة أيام الطبيب، فيخمّن ويحصل على خطأ. أرِه الممكن قبل أن يختار."}}],"hints":[{"en":"Who knows which days Dr. Hany works: Ahmed or the system?","ar":"من يعرف أيام عمل د. هاني: أحمد أم النظام؟"},{"en":"Should Ahmed find out a day is closed before he picks it, or after?","ar":"هل يجب أن يعرف أحمد أن اليوم غير متاح قبل أن يختاره، أم بعده؟"}],"correct":{"en":"Only the system knows: let him pick, and block the rest.","ar":"النظام وحده يعرف: دعه يختار، واحجب الباقي."},"explain":{"en":"Grayed-out days show the doctor's pattern at a glance, and one line says why, so the calendar doesn't look broken.","ar":"الأيام الرمادية تُظهر نمط عمل الطبيب بنظرة واحدة، وسطر واحد يوضّح السبب، فلا يبدو التقويم معطّلًا."},"speaker":"nour"},{"id":"S05","type":"tune","skill":"SK-P01-U02-06","part":"guided","speaker":"sara","rules":["R06","R15"],"value":{"en":"Input steppers (NN/g): use steppers for numeric fields with a clear most-frequent value, and set that value as the default. Most bookings are for two adults.","ar":"الـ Stepper (NN/g): استخدمه للحقول الرقمية التي لها قيمة شائعة واضحة، واجعل تلك القيمة هي الافتراضية. وأغلب الحجوزات لشخصين بالغين."},"ref":{"url":"https://www.nngroup.com/articles/input-steppers/","quote":"Use steppers for numerical fields with a clear most frequently selected value."},"scenario":{"en":"I'm designing a booking form for holiday flats. Hossam is booking one. Adults: 1 to 8, and almost always 2.","ar":"أصمّم نموذج حجز لشقق العطلات. ويحجز حسام شقة. البالغون: من 1 إلى 8، وغالبًا 2."},"prompt":{"en":"Try each control for the number of adults. Which one should ship?","ar":"جرّب كل عنصر لعدد البالغين. أيّها يجب أن يُطلق؟"},"start":"select","options":[{"id":"stepper","text":{"en":"A stepper starting at 2","ar":"Stepper يبدأ من 2"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Adults","ar":"البالغون"},"text":"2"}]}},{"id":"select","text":{"en":"A dropdown from 1 to 8","ar":"قائمة منسدلة من 1 إلى 8"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Adults","ar":"البالغون"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"empty","text":{"en":"An empty number field","ar":"حقل رقم فارغ"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Adults","ar":"البالغون"},"text":""}]}}],"answer":["stepper"],"misconceptions":[{"id":"MC-P01-023","when":["select","empty"],"feedback":{"en":"Almost everyone answers 2, yet each of them has to open a list or type it. Start at 2 and let the few adjust with one tap.","ar":"أغلب الناس يجيبون 2، ومع ذلك على كلٍّ منهم أن يفتح قائمة أو يكتب. ابدأ من 2 ودع القلّة يعدّلون بضغطة واحدة."}}],"hints":[{"en":"Look at the usual answer: almost always 2.","ar":"انظر إلى الإجابة المعتادة: 2 في أغلب الأحيان."},{"en":"Which control shows that usual value already, with a quick way to change it?","ar":"أي عنصر يعرض هذه القيمة المعتادة مسبقًا، مع طريقة سريعة لتغييرها؟"}],"correct":{"en":"Usual value showing, one tap to change.","ar":"القيمة المعتادة ظاهرة، وضغطة واحدة للتغيير."},"explain":{"en":"Most people don't touch it at all, and a family of three taps + once. A default is fine here because it's visible and harmless if left.","ar":"أغلب الناس لا يلمسونه أصلًا، والعائلة من ثلاثة أشخاص تضغط + مرة واحدة. والقيمة الافتراضية مناسبة هنا لأنها ظاهرة وغير ضارة إن تُركت."}},{"id":"S06","type":"tune","skill":"SK-P01-U02-07","part":"guided","speaker":"sara","rules":["R06","R15"],"value":{"en":"Mobile input checklist (NN/g): what is the right keyboard for this field? A 14-digit national ID is a code: it needs the number pad, not a number field with arrows that treats it as an amount.","ar":"قائمة تحقّق حقول الهاتف (NN/g): ما لوحة المفاتيح المناسبة لهذا الحقل؟ والرقم القومي من 14 رقمًا رمز: يحتاج لوحة الأرقام، لا حقل رقم بأسهم يعامله ككمية."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"What is the right keyboard for this field?"},"scenario":{"en":"Back on the library form I'm designing: Abdelrahman's national ID has 14 digits, and we're choosing the field type.","ar":"نعود إلى نموذج المكتبة الذي أصمّمه: الرقم القومي لعبد الرحمن من 14 رقمًا، ونحن نختار نوع الحقل."},"prompt":{"en":"Try each field. Which one should ship?","ar":"جرّب كل حقل. أيّها يجب أن يُطلق؟"},"start":"number","options":[{"id":"number","text":{"en":"A number field with ▲▼ arrows","ar":"حقل رقم بسهمي ▲▼"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"filled":true,"text":"29803121401234 ▲▼"},{"kind":"small","text":{"en":"Treated as an amount: the arrows add or subtract 1.","ar":"يُعامَل ككمية: الأسهم تضيف 1 أو تطرحه."},"gap":"xs"}]}},{"id":"boxes","text":{"en":"Fourteen one-digit boxes","ar":"أربع عشرة خانة، رقم في كل خانة"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"National ID number","ar":"الرقم القومي"}},{"kind":"row","gap":"xs","blocks":[{"kind":"field","text":"2"},{"kind":"field","text":"9"},{"kind":"field","text":"8"},{"kind":"field","text":""},{"kind":"field","text":""},{"kind":"field","text":""},{"kind":"field","text":""}]}]}},{"id":"text","text":{"en":"A text field that opens the number pad","ar":"حقل نص يفتح لوحة الأرقام"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"filled":true,"text":"29803121401234"},{"kind":"small","text":{"en":"Keyboard: 1 2 3 … 0","ar":"لوحة المفاتيح: 1 2 3 … 0"},"gap":"xs"}]}}],"answer":["text"],"misconceptions":[{"id":"MC-P01-021","when":["number"],"feedback":{"en":"A number field treats the ID as an amount: it may round it, drop a leading zero, or change it with a stray scroll. It's a code.","ar":"حقل الرقم يعامل الرقم القومي ككمية: قد يقرّبه، أو يحذف صفرًا في أوله، أو يغيّره بتمرير عابر. إنه رمز."}},{"id":"MC-P01-021","when":["boxes"],"feedback":{"en":"Boxes break pasting and make it easy to skip one. One text field with the number pad does the job.","ar":"الخانات تمنع اللصق وتجعل تخطّي خانة سهلًا. وحقل نص واحد مع لوحة الأرقام يؤدّي المهمة."}}],"hints":[{"en":"Is the ID an amount you could add or round, or a code?","ar":"هل الرقم القومي كمية يمكن جمعها أو تقريبها، أم رمز؟"},{"en":"Which field gives him the number pad without treating it as an amount?","ar":"أي حقل يعطيه لوحة الأرقام دون أن يعامله ككمية؟"}],"correct":{"en":"Digits, but not an amount: text with the number pad.","ar":"أرقام، لكنها ليست كمية: نص مع لوحة الأرقام."},"explain":{"en":"Use number fields only for amounts you'd count or add. IDs, codes and phone numbers are labels that happen to use digits.","ar":"استخدم حقول الأرقام فقط للكميات التي تُعدّ أو تُجمع. والأرقام التعريفية والرموز وأرقام الهواتف تسميات تتكوّن من أرقام."}},{"id":"S07","type":"compare","skill":"SK-P01-U02-06","part":"contrast","speaker":"tarek","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S05: steppers aren't for every number. Input steppers (NN/g): they aren't suitable for large adjustments. A catering order of about 60 portions needs typing.","ar":"مقارنة مع الخطوة 5: الـ Stepper لا يناسب كل رقم. الـ Stepper (NN/g): لا يناسب التعديلات الكبيرة. وطلب ولائم من نحو 60 وجبة يحتاج إلى الكتابة."},"ref":{"url":"https://www.nngroup.com/articles/input-steppers/","quote":"Steppers are not suitable for a large number adjustments."},"scenario":{"en":"In our lunch app, Tamer is ordering for his whole office: 60 portions. Orders on this page range from 20 to 200.","ar":"في تطبيق الغداء عندنا، يطلب تامر لكل مكتبه: 60 وجبة. والطلبات في هذه الصفحة تتراوح بين 20 و200."},"prompt":{"en":"Which control should ship for the number of portions?","ar":"أي عنصر يجب أن يُطلق لعدد الوجبات؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Portions","ar":"عدد الوجبات"},"text":"20"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Portions","ar":"عدد الوجبات"},"filled":true,"text":"60"}]}},"answer":"b","reason":{"prompt":{"en":"Why not a stepper this time?","ar":"لماذا لا نستخدم Stepper هذه المرة؟"},"options":[{"id":"taps","text":{"en":"There's no usual value, and reaching 60 would take 40 taps","ar":"لا توجد قيمة معتادة، والوصول إلى 60 يحتاج 40 ضغطة"}},{"id":"ugly","text":{"en":"Steppers look old-fashioned","ar":"الـ Stepper يبدو قديم الطراز"}},{"id":"big","text":{"en":"Big numbers need a dropdown","ar":"الأرقام الكبيرة تحتاج قائمة منسدلة"}}],"answer":["taps"],"misconceptions":[{"id":"MC-P01-023","when":["ugly","big"],"feedback":{"en":"It's about effort. A stepper shines when most people keep the default or change it by one or two. Here the value is far and varies a lot.","ar":"المسألة مسألة جهد. الـ Stepper ممتاز حين يُبقي أغلب الناس القيمة الافتراضية أو يغيّرونها بواحد أو اثنين. وهنا القيمة بعيدة وتتغيّر كثيرًا."}}]},"misconceptions":[{"id":"MC-P01-023","when":["a"],"feedback":{"en":"From 20 to 60 is forty taps on +. With no usual value and a wide range, typing is faster.","ar":"من 20 إلى 60 تعني أربعين ضغطة على +. ومع غياب قيمة معتادة ومدى واسع، الكتابة أسرع."}}],"hints":[{"en":"Look at the range: 20 to 200, and Tamer needs 60.","ar":"انظر إلى المدى: من 20 إلى 200، وتامر يحتاج 60."},{"en":"How many taps would it take to reach 60 one at a time?","ar":"كم ضغطة يحتاج للوصول إلى 60 واحدة تلو الأخرى؟"}],"correct":{"en":"Wide range, no usual value: type it.","ar":"مدى واسع بلا قيمة معتادة: اكتبه."},"explain":{"en":"A stepper is for small adjustments around a common value. When answers spread widely, a text field with the number pad wins.","ar":"الـ Stepper للتعديلات الصغيرة حول قيمة شائعة. وحين تتباعد الإجابات كثيرًا، يفوز حقل النص مع لوحة الأرقام."}},{"id":"S08","type":"tune","skill":"SK-P01-U02-06","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Sliders (NN/g): a slider is good for exploring a range, but precise values are hard to hit; add a text box for fine control. Tamer has an exact budget.","ar":"حالة جديدة. الـ Sliders (NN/g): الـ Slider جيد لاستكشاف مدى، لكن الوصول إلى قيم دقيقة صعب؛ فأضف حقل نص للضبط الدقيق. ولدى تامر ميزانية محدّدة."},"ref":{"url":"https://www.nngroup.com/articles/sliders-knobs/","quote":"Then, a text box is added to allow for fine control — selecting a specific value."},"scenario":{"en":"Tamer's budget per person is exactly 80 to 120 pounds. Our restaurant filter uses a price slider from 0 to 500.","ar":"ميزانية تامر للفرد بالضبط من 80 إلى 120 جنيهًا. وفلتر المطاعم عندنا يستخدم Slider للسعر من 0 إلى 500."},"prompt":{"en":"Try each filter. Which one should ship?","ar":"جرّب كل فلتر. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now (try to set 80 to 120)","ar":"الآن (جرّب أن تضبطه من 80 إلى 120)"},"width":300,"blocks":[{"kind":"slider","label":{"en":"Price per person","ar":"السعر للفرد"},"min":0,"max":500,"from":100,"to":325,"format":{"en":"From {a} to {b} pounds","ar":"من {a} إلى {b} جنيهًا"}}]},"options":[{"id":"wide","text":{"en":"Make the slider wider","ar":"اجعل الـ Slider أعرض"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":320,"blocks":[{"kind":"slider","label":{"en":"Price per person","ar":"السعر للفرد"},"min":0,"max":500,"from":100,"to":325,"format":{"en":"From {a} to {b} pounds","ar":"من {a} إلى {b} جنيهًا"}}]}},{"id":"both","text":{"en":"Keep the slider, and add Min and Max fields","ar":"أبقِ الـ Slider، وأضف حقلين للأقل والأعلى"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"slider","label":{"en":"Price per person","ar":"السعر للفرد"},"min":0,"max":500,"from":80,"to":120,"format":{"en":"From {a} to {b} pounds","ar":"من {a} إلى {b} جنيهًا"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","label":{"en":"Min","ar":"الأقل"},"filled":true,"text":"80"},{"kind":"field","label":{"en":"Max","ar":"الأعلى"},"filled":true,"text":"120"}]}]}},{"id":"ranges","text":{"en":"Replace it with fixed ranges","ar":"استبدله بنطاقات ثابتة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Price per person","ar":"السعر للفرد"}},{"kind":"radio","text":{"en":"Under 100","ar":"أقل من 100"},"gap":"xs"},{"kind":"radio","text":{"en":"100 to 200","ar":"من 100 إلى 200"},"gap":"xs"},{"kind":"radio","text":{"en":"Over 200","ar":"أكثر من 200"},"gap":"xs"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-022","when":["wide"],"feedback":{"en":"A few more pixels still means each step jumps a few pounds on a phone. He needs a place to type 80.","ar":"بضع نقاط إضافية تعني أن كل خطوة ما زالت تقفز بضعة جنيهات على الهاتف. يحتاج مكانًا يكتب فيه 80."}},{"id":"MC-P01-022","when":["ranges"],"feedback":{"en":"His 80 to 120 crosses two ranges, so he can't express it at all. Let him set exact values.","ar":"نطاقه من 80 إلى 120 يقع بين نطاقين، فلا يستطيع التعبير عنه أصلًا. دعه يضبط قيمًا دقيقة."}}],"hints":[{"en":"Tamer knows his exact numbers. Can he set exactly 80 and 120 by dragging?","ar":"تامر يعرف أرقامه بالضبط. هل يستطيع ضبط 80 و120 بالضبط بالسحب؟"},{"en":"A slider is good for exploring. What's good for being exact?","ar":"الـ Slider مناسب للاستكشاف. ما المناسب للدقة؟"}],"correct":{"en":"Slider to explore, fields to be exact.","ar":"الـ Slider للاستكشاف، والحقول للدقة."},"explain":{"en":"The slider shows the whole price range at a glance; the fields let Tamer set exactly what he has. Linked together, each serves a different need.","ar":"الـ Slider يعرض مدى الأسعار كله بنظرة؛ والحقول تتيح لتامر ضبط ما لديه بالضبط. ومعًا، يخدم كلٌّ منهما حاجة مختلفة."}},{"id":"S09","type":"card","part":"recap","icons":["form","clock","list","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Known by heart:** let Ahmed type his date of birth.\n- **Known only by the system:** showed the doctor's free days and blocked the rest.\n- **Small usual counts:** used a stepper starting at 2.\n- **Codes:** used a text field with the number pad for the ID.\n- **Large or exact numbers:** typed fields, with a slider only for exploring.\n\nNext lesson: long lists, and search that finds what people type.","ar":"- **ما يُحفظ عن ظهر قلب:** دع أحمد يكتب تاريخ ميلاده.\n- **ما لا يعرفه إلا النظام:** عرضت أيام الطبيب المتاحة وحجبت الباقي.\n- **الأعداد الصغيرة المعتادة:** استخدمت Stepper يبدأ من 2.\n- **الرموز:** استخدمت حقل نص مع لوحة الأرقام للرقم القومي.\n- **الأرقام الكبيرة أو الدقيقة:** حقول للكتابة، والـ Slider للاستكشاف فقط.\n\nالدرس التالي: القوائم الطويلة، والبحث الذي يجد ما يكتبه الناس."}}]}$uxg$::jsonb),
  ($uxg$P01-U02-L03$uxg$, $uxg$48643df20cdd61a745b95a399a74fbada4398f915575731aad44bfe768d1751d$uxg$, $uxg${"id":"P01-U02-L03","mode":"lesson","minutes":8,"title":{"en":"Long lists: let people type","ar":"القوائم الطويلة: دع الناس يكتبون"},"speaker":"sara","review_labels":{"MC-P01-012":{"en":"Let people type what they know by heart","ar":"دع الناس يكتبون ما يحفظونه"},"MC-P01-015":{"en":"Don't preselect a guess for a personal answer","ar":"لا تحدّد تخمينًا مسبقًا لإجابة شخصية"},"MC-P01-016":{"en":"Long lists need a way to search","ar":"القوائم الطويلة تحتاج طريقة للبحث"},"MC-P01-024":{"en":"Search should accept how people really type","ar":"البحث يجب أن يقبل ما يكتبه الناس فعلًا"},"MC-P01-025":{"en":"Pin common options; keep the full list","ar":"ثبّت الخيارات الشائعة في الأعلى، واحتفظ بالقائمة كاملة"},"MC-P01-031":{"en":"Show a few options; don't hide them in a dropdown","ar":"اعرض الخيارات القليلة؛ لا تُخفِها في قائمة منسدلة"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Abdelrahman's nationality","ar":"جنسية عبد الرحمن"},"body":{"en":"The library form I'm designing asks for Abdelrahman's nationality. Tapping the field opens a list of about 195 countries, from A to Z.\n\nEgypt is about a quarter of the way down.","ar":"يسأل نموذج المكتبة الذي أصمّمه عن جنسية عبد الرحمن. والضغط على الحقل يفتح قائمة بنحو 195 دولة، مرتّبة أبجديًا.\n\nومصر في مكان ما بعد ربع القائمة."},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Nationality","ar":"الجنسية"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan","ar":"أفغانستان"}},{"kind":"text","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"text","text":{"en":"Algeria","ar":"الجزائر"},"gap":"xs"},{"kind":"text","text":{"en":"Andorra","ar":"أندورا"},"gap":"xs"},{"kind":"small","text":{"en":"… 191 more","ar":"… 191 دولة أخرى"},"gap":"xs"}]}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-08","part":"try","rules":["R12"],"value":{"en":"Try first. Dropdown lists (NN/g): when a list grows well beyond 15 options, consider a combobox; people type and the list narrows. It works well for long, predictable lists such as countries.","ar":"جرّب أولًا. القوائم المنسدلة (NN/g): حين تتجاوز القائمة 15 خيارًا بكثير، فكّر في Combobox؛ يكتب الناس فتضيق القائمة. وهو يعمل جيدًا مع القوائم الطويلة المتوقّعة مثل الدول."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"This pattern works well for long lists of predictable options such as countries, states, languages, and universities."},"prompt":{"en":"Try each way of choosing a country. Which one should ship?","ar":"جرّب كل طريقة لاختيار الدولة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"select","label":{"en":"Nationality","ar":"الجنسية"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan","ar":"أفغانستان"}},{"kind":"text","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"text","text":{"en":"Algeria","ar":"الجزائر"},"gap":"xs"},{"kind":"text","text":{"en":"Andorra","ar":"أندورا"},"gap":"xs"},{"kind":"small","text":{"en":"… 191 more","ar":"… 191 دولة أخرى"},"gap":"xs"}]}]},"options":[{"id":"radios","text":{"en":"Show all 195 as radio buttons","ar":"اعرض الـ 195 كلها كـ Radio buttons"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Nationality","ar":"الجنسية"}},{"kind":"radio","text":{"en":"Afghanistan","ar":"أفغانستان"},"gap":"xs"},{"kind":"radio","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"radio","text":{"en":"Algeria","ar":"الجزائر"},"gap":"xs"},{"kind":"radio","text":{"en":"Andorra","ar":"أندورا"},"gap":"xs"},{"kind":"small","text":{"en":"… 191 more, about 12 screens","ar":"… 191 دولة أخرى، نحو 12 شاشة"},"gap":"xs"}]}},{"id":"split","text":{"en":"Pick a continent first, then the country","ar":"اختر القارة أولًا، ثم الدولة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Continent","ar":"القارة"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"select","label":{"en":"Nationality","ar":"الجنسية"},"text":{"en":"Select…","ar":"اختر…"},"gap":"s"}]}},{"id":"combo","text":{"en":"A field he types into; the list narrows as he types","ar":"حقل يكتب فيه؛ وتضيق القائمة مع الكتابة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Eg","ar":"مص"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","weight":"bold","text":{"en":"Egypt","ar":"مصر"}}]}]}}],"answer":["combo"],"misconceptions":[{"id":"MC-P01-016","when":["radios"],"feedback":{"en":"Now every choice is visible, but he scrolls through a dozen screens to find Egypt. A long list needs typing, not more scrolling.","ar":"الآن كل الخيارات ظاهرة، لكنه يمرّر عشرات الشاشات ليجد مصر. والقائمة الطويلة تحتاج كتابة، لا مزيدًا من التمرير."}},{"id":"MC-P01-016","when":["split"],"feedback":{"en":"Two lists instead of one, and he has to know how the form groups countries. Typing two letters is faster than both.","ar":"قائمتان بدل واحدة، وعليه أن يعرف كيف يقسّم النموذج الدول. وكتابة حرفين أسرع من الاثنين."}}],"hints":[{"en":"Abdelrahman already knows the answer. What's the quickest way to reach Egypt?","ar":"عبد الرحمن يعرف الإجابة مسبقًا. ما أسرع طريقة للوصول إلى مصر؟"},{"en":"Scrolling 195 options or picking a continent first both take time. What lets him go straight there?","ar":"التمرير بين 195 خيارًا أو اختيار القارة أولًا كلاهما يأخذ وقتًا. ما الذي يوصله مباشرة؟"}],"correct":{"en":"Long, known list: type to filter.","ar":"قائمة طويلة معروفة: اكتب لتضييقها."},"explain":{"en":"Abdelrahman knows the answer. Two letters bring it to the top, and the list still guarantees a valid country.","ar":"عبد الرحمن يعرف الإجابة. وحرفان يُظهرانها في الأعلى، والقائمة تضمن مع ذلك اسم دولة صحيحًا."}},{"id":"S03","type":"card","part":"concept","icons":["list","eye","form","idea"],"title":{"en":"Let the list come to them","ar":"دع القائمة تأتي إليهم"},"body":{"en":"Dropdowns hide their options. That's fine for a short list, and slow for a long one.\n\n- **A handful of options:** show them, as radio buttons.\n- **Well over 15 options people know, like countries:** a field that filters as they type.\n- **Values people know by heart, like a year:** a plain text field.\n- **Forgive spelling:** people rarely type perfectly. Suggest close matches as they type.\n- **Pin, don't preselect:** put the most common choices at the top, but let each person choose. People often keep whatever is already selected.","ar":"القوائم المنسدلة تُخفي خياراتها. وهذا مناسب للقائمة القصيرة، وبطيء للطويلة.\n\n- **خيارات قليلة:** اعرضها، كـ Radio buttons.\n- **أكثر من 15 خيارًا بكثير يعرفها الناس، مثل الدول:** حقل يضيّق القائمة مع الكتابة.\n- **قيم يحفظها الناس، مثل سنة:** حقل نص عادي.\n- **سامح في الإملاء:** نادرًا ما يكتب الناس بدقة. فاقترح أقرب النتائج أثناء الكتابة.\n- **ثبّت ولا تحدّد مسبقًا:** ضع الخيارات الأكثر شيوعًا في الأعلى، لكن دع كل شخص يختار. فالناس كثيرًا ما يُبقون ما هو محدّد بالفعل."}},{"id":"S04","type":"tune","skill":"SK-P01-U02-08","part":"guided","rules":["R06","R15"],"value":{"en":"Site search (NN/g): users often don't formulate perfect queries; spelling suggestions are critical. A filter that needs exact spelling turns a shortcut into a test.","ar":"البحث في الموقع (NN/g): كثيرًا ما لا يصوغ المستخدمون استعلامات مثالية؛ واقتراحات الإملاء ضرورية. والفلتر الذي يطلب إملاءً دقيقًا يحوّل الاختصار إلى اختبار."},"ref":{"url":"https://www.nngroup.com/articles/internal-website-search/","quote":"Users often don’t formulate perfect queries."},"scenario":{"en":"In testing, Abdelrahman typed quickly with one thumb: \"Egipt\".","ar":"في الاختبار، كتب عبد الرحمن بسرعة بإبهام واحد: «مصرر»."},"prompt":{"en":"Try each way the field can respond. Which one should ship?","ar":"جرّب كل طريقة يمكن أن يستجيب بها الحقل. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"close","text":{"en":"Show the closest match","ar":"اعرض أقرب نتيجة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Egipt","ar":"مصرر"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"small","text":{"en":"Did you mean:","ar":"هل تقصد:"}},{"kind":"text","weight":"bold","text":{"en":"Egypt","ar":"مصر"},"gap":"xs"}]}]}},{"id":"none","text":{"en":"Show \"No results\"","ar":"اعرض «لا توجد نتائج»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Egipt","ar":"مصرر"}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]}},{"id":"all","text":{"en":"Show the whole list again","ar":"اعرض القائمة كلها من جديد"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Egipt","ar":"مصرر"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan","ar":"أفغانستان"}},{"kind":"text","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"small","text":{"en":"… 193 more","ar":"… 193 دولة أخرى"},"gap":"xs"}]}]}}],"answer":["close"],"misconceptions":[{"id":"MC-P01-024","when":["none"],"feedback":{"en":"One wrong letter and a dead end. He has to spot the typo himself. The system can see that \"Egipt\" is almost certainly Egypt.","ar":"حرف خاطئ واحد وطريق مسدود. وعليه أن يكتشف الخطأ بنفسه. بينما يستطيع النظام أن يرى أن ما كتبه هو مصر على الأرجح."}},{"id":"MC-P01-024","when":["all"],"feedback":{"en":"His typing is thrown away and he's back to scrolling 195 countries. Use what he typed to guess what he meant.","ar":"ضاعت كتابته وعاد إلى تمرير 195 دولة. استخدم ما كتبه لتخمين ما يقصده."}}],"hints":[{"en":"He made one small typo. Is \"Egipt\" close to a country in the list?","ar":"أخطأ خطأً صغيرًا واحدًا. هل «Egipt» قريبة من دولة في القائمة؟"},{"en":"Which response helps him without making him start again?","ar":"أي استجابة تساعده دون أن تجعله يبدأ من جديد؟"}],"correct":{"en":"Close enough should still land.","ar":"القريب يجب أن يصل أيضًا."},"explain":{"en":"Matching near misses, and saying so, rescues most typos in one tap. People don't need to type perfectly to get the right answer.","ar":"مطابقة الأخطاء القريبة، مع توضيح ذلك، تُنقذ أغلب الأخطاء الإملائية بضغطة واحدة. ولا يحتاج الناس إلى الكتابة بدقة ليصلوا إلى الإجابة الصحيحة."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U02-08","part":"guided","rules":["R06","R15"],"value":{"en":"Dropdown lists (NN/g): users may not explore options beyond the default. Preselecting the common country creates silent errors for everyone else; pinning gives the speed without the risk.","ar":"القوائم المنسدلة (NN/g): قد لا يستكشف المستخدمون خيارات غير الخيار الافتراضي. وتحديد الدولة الشائعة مسبقًا يصنع أخطاء صامتة لكل الآخرين؛ أما التثبيت في الأعلى فيعطي السرعة بلا خطر."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"Users may not interact with the control to explore additional options beyond the default."},"scenario":{"en":"Another client's sign-up form asks for a phone country code. Most of their users are in Egypt or Saudi Arabia. Fadi lives in Jordan and is in a hurry.","ar":"نموذج التسجيل لدى عميل آخر يطلب رمز الدولة للهاتف. وأغلب مستخدميه في مصر أو السعودية. وفادي يعيش في الأردن ومستعجل."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"preset","options":[{"id":"preset","text":{"en":"Preselect Egypt (⁦+20⁩)","ar":"حدّد مصر (‎⁦+20⁩) مسبقًا"},"mock":{"width":300,"blocks":[{"kind":"row","gap":"s","blocks":[{"kind":"select","label":{"en":"Code","ar":"الرمز"},"filled":true,"text":"⁦+20⁩"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦79 123 4567⁩"}]},{"kind":"small","color":"red","text":{"en":"Saved as ⁦+20 79 123 4567⁩: not Fadi's number","ar":"حُفظ هكذا: ‎⁦+20 79 123 4567⁩، وهو ليس رقم فادي"},"gap":"xs"}]}},{"id":"pin","text":{"en":"Pin Egypt and Saudi Arabia at the top; nothing selected","ar":"ثبّت مصر والسعودية في الأعلى؛ دون تحديد أي شيء"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Country code","ar":"رمز الدولة"},"text":{"en":"Choose or type a country","ar":"اختر دولة أو اكتب اسمها"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Egypt ⁦+20⁩","ar":"مصر ‎⁦+20⁩"}},{"kind":"text","text":{"en":"Saudi Arabia ⁦+966⁩","ar":"السعودية ‎⁦+966⁩"},"gap":"xs"},{"kind":"divider","gap":"xs"},{"kind":"text","text":{"en":"Afghanistan ⁦+93⁩","ar":"أفغانستان ‎⁦+93⁩"},"gap":"xs"},{"kind":"small","text":{"en":"… all countries, A to Z","ar":"… كل الدول، أبجديًا"},"gap":"xs"}]}]}},{"id":"az","text":{"en":"Plain A to Z list, nothing pinned or selected","ar":"قائمة أبجدية عادية، دون تثبيت أو تحديد"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Country code","ar":"رمز الدولة"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan ⁦+93⁩","ar":"أفغانستان ‎⁦+93⁩"}},{"kind":"text","text":{"en":"Albania ⁦+355⁩","ar":"ألبانيا ‎⁦+355⁩"},"gap":"xs"},{"kind":"small","text":{"en":"… Egypt is about 60 rows down","ar":"… مصر بعد نحو 60 سطرًا"},"gap":"xs"}]}]}}],"answer":["pin"],"misconceptions":[{"id":"MC-P01-015","when":["preset"],"feedback":{"en":"Fadi types his number and never notices ⁦+20⁩. The account gets a wrong number, and nobody knows until a code never arrives.","ar":"يكتب فادي رقمه ولا يلاحظ ‎⁦+20⁩ أبدًا. فيُسجَّل في الحساب رقم خاطئ، ولا يعرف أحد حتى لا يصل رمز التحقق."}},{"id":"MC-P01-025","when":["az"],"feedback":{"en":"Safe for Fadi, but most users scroll past dozens of countries every time. Pin the common ones on top of the full list.","ar":"آمن لفادي، لكن أغلب المستخدمين يمرّرون عشرات الدول في كل مرة. ثبّت الشائعة فوق القائمة الكاملة."}}],"hints":[{"en":"Fadi lives in Jordan. What happens if he doesn't notice a preselected code?","ar":"فادي يعيش في الأردن. ماذا يحدث إن لم ينتبه إلى رمز محدّد مسبقًا؟"},{"en":"How can most people save time without anyone getting a wrong answer by default?","ar":"كيف يوفّر أغلب الناس الوقت دون أن يحصل أحد على إجابة خاطئة تلقائيًا؟"}],"correct":{"en":"Pin the common ones; let each person choose.","ar":"ثبّت الشائعة؛ ودع كل شخص يختار."},"explain":{"en":"Pinning puts most people one tap away without choosing for anyone. Keep the pinned group small, two to five items, or it becomes another long list.","ar":"التثبيت يجعل أغلب الناس على بُعد ضغطة واحدة دون أن يختار عن أحد. واجعل المجموعة المثبّتة صغيرة، من اثنين إلى خمسة، وإلا صارت قائمة طويلة أخرى."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U02-04","part":"guided","rules":["R06","R15"],"value":{"en":"Dropdown lists (NN/g): for readily known values, typing is often faster than selecting from a dropdown. A year has 4 digits and everyone knows theirs.","ar":"القوائم المنسدلة (NN/g): للقيم المعروفة، الكتابة غالبًا أسرع من الاختيار من قائمة منسدلة. والسنة 4 أرقام والكل يعرف سنته."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"For readily known values — ages, birthdates, heights — typing is often faster than selecting from a dropdown."},"scenario":{"en":"The library asks the year Abdelrahman finished school. The dropdown lists every year from 2026 back to 1950. He finished in 2009.","ar":"تسأل المكتبة عن السنة التي أنهى فيها عبد الرحمن الدراسة. والقائمة المنسدلة تعرض كل السنوات من 2026 حتى 1950. وقد أنهاها في 2009."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"list","options":[{"id":"list","text":{"en":"Keep the dropdown of 77 years","ar":"أبقِ القائمة المنسدلة ذات الـ 77 سنة"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Year you finished school","ar":"سنة إنهاء الدراسة"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"combo","text":{"en":"A search field that filters the years","ar":"حقل بحث يضيّق قائمة السنوات"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Year you finished school","ar":"سنة إنهاء الدراسة"},"filled":true,"text":"20"},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":"2026"},{"kind":"text","text":"2025","gap":"xs"},{"kind":"small","text":{"en":"… 25 more","ar":"… 25 سنة أخرى"},"gap":"xs"}]}]}},{"id":"type","text":{"en":"A short text field for the year","ar":"حقل نص قصير للسنة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Year you finished school","ar":"سنة إنهاء الدراسة"},"filled":true,"text":"2009"}]}}],"answer":["type"],"misconceptions":[{"id":"MC-P01-012","when":["list"],"feedback":{"en":"He knows the answer, yet has to scroll 17 years to reach it. Four keystrokes are faster than any list.","ar":"يعرف الإجابة، ومع ذلك عليه أن يمرّر 17 سنة ليصل إليها. وأربع ضغطات أسرع من أي قائمة."}},{"id":"MC-P01-012","when":["combo"],"feedback":{"en":"Filtering helps with names people might spell differently. A year has one spelling; just let him type it.","ar":"التضييق يساعد مع الأسماء التي قد تُكتب بأشكال مختلفة. والسنة لها كتابة واحدة؛ فدعه يكتبها فقط."}}],"hints":[{"en":"Does Abdelrahman need to search for 2009, or does he know it by heart?","ar":"هل يحتاج عبد الرحمن إلى البحث عن 2009، أم يعرفها جيدًا؟"},{"en":"A year has one way to write it. What's the fewest steps to enter it?","ar":"السنة تُكتب بطريقة واحدة فقط. ما أقل عدد من الخطوات لإدخالها؟"}],"correct":{"en":"Known value, one spelling: type it.","ar":"قيمة معروفة بكتابة واحدة: تُكتب."},"explain":{"en":"Not every answer needs a list. When people know the value and it can only be written one way, a text field is the fastest control there is.","ar":"ليست كل إجابة تحتاج قائمة. وحين يعرف الناس القيمة ولا تُكتب إلا بطريقة واحدة، فحقل النص هو أسرع عنصر ممكن."},"speaker":"sara"},{"id":"S07","type":"compare","skill":"SK-P01-U02-02","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S02: search is for long lists. Dropdown lists (NN/g): for a handful of options, radio buttons are universally understood, show every choice and take one click.","ar":"مقارنة مع الخطوة 2: البحث للقوائم الطويلة. القوائم المنسدلة (NN/g): مع خيارات قليلة، الـ Radio buttons مفهومة للجميع، وتعرض كل الخيارات وتحتاج ضغطة واحدة."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"They are universally understood, expose all choices immediately, and require only a single click to select an option."},"scenario":{"en":"The library has four branches. Abdelrahman picks the one where he'll collect his card.","ar":"للمكتبة أربعة فروع. ويختار عبد الرحمن الفرع الذي سيستلم منه بطاقته."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Branch","ar":"الفرع"},"text":{"en":"Type a branch name","ar":"اكتب اسم الفرع"}}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Branch","ar":"الفرع"}},{"kind":"radio","text":{"en":"Downtown","ar":"وسط البلد"},"gap":"xs"},{"kind":"radio","text":{"en":"Heliopolis","ar":"مصر الجديدة"},"gap":"xs"},{"kind":"radio","text":{"en":"Maadi","ar":"المعادي"},"gap":"xs"},{"kind":"radio","text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"xs"}]}},"answer":"b","reason":{"prompt":{"en":"Why not a search field here, when it was right for countries?","ar":"لماذا لا نستخدم حقل بحث هنا، مع أنه كان صحيحًا للدول؟"},"options":[{"id":"few","text":{"en":"Four choices fit on screen, and he may not know their names","ar":"أربعة خيارات تتّسع على الشاشة، وقد لا يعرف أسماءها"}},{"id":"modern","text":{"en":"Radio buttons look friendlier","ar":"الـ Radio buttons تبدو ألطف"}},{"id":"type","text":{"en":"Typing is always slower","ar":"الكتابة أبطأ دائمًا"}}],"answer":["few"],"misconceptions":[{"id":"MC-P01-031","when":["modern","type"],"feedback":{"en":"Typing was faster for 195 countries he knows. Here there are four branches he may not know: showing them is faster and teaches him the options.","ar":"الكتابة كانت أسرع مع 195 دولة يعرفها. وهنا أربعة فروع قد لا يعرفها: وعرضها أسرع ويعرّفه بالخيارات."}}]},"misconceptions":[{"id":"MC-P01-031","when":["a"],"feedback":{"en":"He'd have to guess the branch names before he can type one. With four, just show them.","ar":"عليه أن يخمّن أسماء الفروع قبل أن يكتب أحدها. ومع أربعة فروع، اعرضها فقط."}}],"hints":[{"en":"Count the branches.","ar":"عُدّ الفروع."},{"en":"With only four choices, should he have to open anything to see them?","ar":"مع أربعة خيارات فقط، هل يجب أن يفتح شيئًا لكي يراها؟"}],"correct":{"en":"A handful: show them all.","ar":"خيارات قليلة: اعرضها كلها."},"explain":{"en":"The size of the list decides. A few options: show them. Dozens that people know: let them type. A value they know by heart: a plain field.","ar":"حجم القائمة هو ما يحدّد. خيارات قليلة: اعرضها. وعشرات يعرفها الناس: دعهم يكتبون. وقيمة يحفظونها: حقل عادي."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P01-U02-08","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Site search (NN/g): query suggestions help people fix spelling errors while they are typing. Place names have many spellings across Arabic and English.","ar":"حالة جديدة. البحث في الموقع (NN/g): اقتراحات البحث تساعد الناس على تصحيح الأخطاء الإملائية أثناء الكتابة. وأسماء الأماكن لها كتابات كثيرة بين العربية والإنجليزية."},"ref":{"url":"https://www.nngroup.com/articles/internal-website-search/","quote":"Oftentimes query suggestions will assist users in adjusting spelling errors while they are typing the query."},"scenario":{"en":"Our lunch app delivers to about 300 areas. Tamer types his area the way he says it: \"Zamalik\".","ar":"يوصّل تطبيق الغداء عندنا إلى نحو 300 منطقة. ويكتب تامر منطقته كما ينطقها: «زملك»."},"prompt":{"en":"Try each version of the area field. Which one should ship?","ar":"جرّب كل نسخة من حقل المنطقة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"filled":true,"text":{"en":"Zamalik","ar":"زملك"}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]},"options":[{"id":"suggest","text":{"en":"Suggest close matches as he types","ar":"اقترح أقرب النتائج أثناء الكتابة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"filled":true,"text":{"en":"Zamal","ar":"زمل"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","weight":"bold","text":{"en":"Zamalek","ar":"الزمالك"}}]}]}},{"id":"hint","text":{"en":"Add \"Type the name exactly as on the map\"","ar":"أضف «اكتب الاسم كما هو على الخريطة تمامًا»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"filled":true,"text":{"en":"Zamalik","ar":"زملك"},"hint":{"en":"Type the name exactly as on the map.","ar":"اكتب الاسم كما هو على الخريطة تمامًا."}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]}},{"id":"list","text":{"en":"Replace it with a dropdown of all 300 areas","ar":"استبدله بقائمة منسدلة لكل الـ 300 منطقة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"small","text":{"en":"300 areas, A to Z","ar":"300 منطقة، أبجديًا"},"gap":"xs"}]}}],"answer":["suggest"],"misconceptions":[{"id":"MC-P01-024","when":["hint"],"feedback":{"en":"Tamer has no way to know the map's spelling. The hint blames him for a problem the search could solve.","ar":"لا يستطيع تامر معرفة كتابة الخريطة. والتلميح يلومه على مشكلة يستطيع البحث حلّها."}},{"id":"MC-P01-016","when":["list"],"feedback":{"en":"He'd scroll through 300 areas to find Z. A long list needs a forgiving search, not a longer scroll.","ar":"سيمرّر 300 منطقة ليصل إلى الزاي. والقائمة الطويلة تحتاج بحثًا متسامحًا، لا تمريرًا أطول."}}],"hints":[{"en":"Tamer typed the name the way he says it. Is it close to a real area?","ar":"كتب تامر الاسم كما ينطقه. هل هو قريب من منطقة حقيقية؟"},{"en":"Should the field ask him to be exact, or help him get there?","ar":"هل يجب أن يطلب منه الحقل الدقة، أم يساعده للوصول؟"}],"correct":{"en":"Meet him halfway while he types.","ar":"قابِله في منتصف الطريق أثناء الكتابة."},"explain":{"en":"Suggestions appear before he finishes, so a near spelling still lands on Zamalek. Fewer dead ends, and no spelling test.","ar":"تظهر الاقتراحات قبل أن ينتهي من الكتابة، فتصل الكتابة القريبة إلى الزمالك. طرق مسدودة أقل، وبلا اختبار إملاء."}},{"id":"S09","type":"card","part":"recap","icons":["list","eye","form","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Long, known lists:** let people type to filter, like countries.\n- **Forgiving search:** suggested close matches instead of \"No results\".\n- **Pin, don't preselect:** put common choices on top and let each person choose.\n- **Known values:** used a plain field for the year.\n- **A handful of options:** showed them as radio buttons.\n\nNext: the unit skill check.","ar":"- **القوائم الطويلة المعروفة:** دع الناس يكتبون لتضييقها، مثل الدول.\n- **بحث متسامح:** اقترحت أقرب النتائج بدل «لا توجد نتائج».\n- **ثبّت ولا تحدّد مسبقًا:** ضع الخيارات الشائعة في الأعلى ودع كل شخص يختار.\n- **القيم المعروفة:** استخدمت حقلًا عاديًا للسنة.\n- **خيارات قليلة:** عرضتها كـ Radio buttons.\n\nالتالي: اختبار المهارة للوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U02-L04$uxg$, $uxg$6e8b3ac9bf8741361428a4e81def7c9de70ef1d89cd9c75c02c7dded2be9bb8f$uxg$, $uxg${"id":"P01-U02-L04","mode":"check","minutes":7,"title":{"en":"Skill check: pick the right control","ar":"اختبار المهارة: اختر عنصر التحكّم المناسب"},"speaker":"sara","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Laila's home cleaning booking","ar":"حجز تنظيف منزل ليلى"},"body":{"en":"My client is a home cleaning company. Laila lives in Heliopolis. She's booking a 4-hour cleaning with ironing and windows, on a day the company has a free team. Her building's door code is 0427.\n\nYour job: choose the right control for each part of the booking form.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"عميلي شركة تنظيف منزلي. تعيش ليلى في مصر الجديدة، وتحجز تنظيفًا لمدة 4 ساعات مع كيّ الملابس والنوافذ، في يوم فيه فريق متاح لدى الشركة. ورمز باب عمارتها 0427.\n\nمهمّتك: اختر عنصر التحكّم المناسب لكل جزء من نموذج الحجز.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Book a home cleaning","ar":"احجز تنظيف منزل"}},{"kind":"select","label":{"en":"Add-ons","ar":"خدمات إضافية"},"text":{"en":"Select one…","ar":"اختر واحدًا…"},"gap":"m"},{"kind":"select","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"text":{"en":"Select…","ar":"اختر…"},"gap":"s"},{"kind":"select","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"toggle","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"},"gap":"m"},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-02","part":"check","rules":["R19"],"value":{"en":"Skill check, checkboxes (NN/g): a checkbox list lets people select one, several, all, or none. Add-ons are any number; a single-select dropdown loses Laila's second add-on.","ar":"اختبار مهارة، الـ Checkboxes (NN/g): قائمة الـ Checkboxes تتيح اختيار واحد أو عدة أو الكل أو لا شيء. والخدمات الإضافية أي عدد؛ والقائمة المنسدلة ذات الاختيار الواحد تُضيّع الخدمة الثانية لليلى."},"ref":{"url":"https://www.nngroup.com/articles/checkboxes-design-guidelines/","quote":"A checkbox list allows users the unique ability to select one, several, all, or no items from a list."},"scenario":{"en":"Laila wants both ironing and windows. On the current form, the add-ons are a dropdown that takes one choice.","ar":"تريد ليلى كيّ الملابس والنوافذ معًا. وفي النموذج الحالي، الخدمات الإضافية قائمة منسدلة تقبل اختيارًا واحدًا."},"prompt":{"en":"Try each control for the add-ons. Which one should ship?","ar":"جرّب كل عنصر للخدمات الإضافية. أيّها يجب أن يُطلق؟"},"start":"select","options":[{"id":"select","text":{"en":"A dropdown, one choice","ar":"قائمة منسدلة، اختيار واحد"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Add-ons","ar":"خدمات إضافية"},"filled":true,"text":{"en":"Ironing","ar":"كيّ الملابس"}}]}},{"id":"radio","text":{"en":"Radio buttons","ar":"Radio buttons"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Add-ons","ar":"خدمات إضافية"}},{"kind":"radio","selected":true,"text":{"en":"Ironing","ar":"كيّ الملابس"},"gap":"xs"},{"kind":"radio","text":{"en":"Windows","ar":"النوافذ"},"gap":"xs"}]}},{"id":"check","text":{"en":"Checkboxes","ar":"Checkboxes"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Add-ons (tick any)","ar":"خدمات إضافية (حدّد ما تريد)"}},{"kind":"check","selected":true,"text":{"en":"Ironing","ar":"كيّ الملابس"},"gap":"xs"},{"kind":"check","selected":true,"text":{"en":"Windows","ar":"النوافذ"},"gap":"xs"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-032","when":["select","radio"],"feedback":{"en":"This control takes one answer, so Laila can't book both. Add-ons are any number, including none: checkboxes.","ar":"هذا العنصر يقبل إجابة واحدة، فلا تستطيع ليلى حجز الاثنين. والخدمات الإضافية أي عدد، حتى لا شيء: Checkboxes."}}],"explain":{"en":"From Lesson 1: one answer, radio buttons; any number, checkboxes.","ar":"من الدرس 1: إجابة واحدة، Radio buttons؛ وأي عدد، Checkboxes."},"speaker":"sara"},{"id":"S03","type":"tune","skill":"SK-P01-U02-01","part":"check","rules":["R19"],"value":{"en":"Skill check, toggle switches (NN/g): separate controls with instant results from ones that wait for a button. The text-me option is only saved when Laila books.","ar":"اختبار مهارة، الـ Toggle switches (NN/g): افصل العناصر ذات النتيجة الفورية عن تلك التي تنتظر زرًا. وخيار الرسالة لا يُحفظ إلا حين تحجز ليلى."},"ref":{"url":"https://www.nngroup.com/articles/toggle-switch-guidelines/","quote":"Separate controls that produce instant results from those that require clicking a command button."},"scenario":{"en":"\"Text me when the team is on the way\" is a toggle above Book cleaning. Nothing is saved until she books.","ar":"«أرسل لي رسالة حين يكون الفريق في الطريق» Toggle فوق «احجز التنظيف». ولا يُحفظ شيء حتى تحجز."},"prompt":{"en":"Try each control. Which one should ship?","ar":"جرّب كل عنصر. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"toggle","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]},"options":[{"id":"keep","text":{"en":"Keep the toggle","ar":"أبقِ الـ Toggle"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"toggle","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}},{"id":"check","text":{"en":"A checkbox, saved with the booking","ar":"Checkbox يُحفظ مع الحجز"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"check","selected":true,"text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}},{"id":"segs","text":{"en":"A segmented control: On / Off","ar":"Segmented control: تشغيل / إيقاف"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"segmented","options":[{"en":"On","ar":"تشغيل"},{"en":"Off","ar":"إيقاف"}],"value":1,"gap":"xs"},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-018","when":["keep"],"feedback":{"en":"A toggle looks like it works the moment it's flipped. In a form that waits for Book cleaning, use a checkbox.","ar":"الـ Toggle يبدو كأنه يعمل لحظة تحريكه. وفي نموذج ينتظر «احجز التنظيف»، استخدم Checkbox."}},{"id":"MC-P01-018","when":["segs"],"feedback":{"en":"On / Off segments look like a live setting too, and take more space. A single checkbox says \"include this with my booking\".","ar":"أزرار تشغيل/إيقاف تبدو أيضًا كإعداد يعمل فورًا، وتأخذ مساحة أكبر. وCheckbox واحد يقول «أضِف هذا إلى حجزي»."}}],"explain":{"en":"From Lesson 1: toggles act now; in a form that waits for a button, use a checkbox.","ar":"من الدرس 1: الـ Toggle يعمل فورًا؛ وفي نموذج ينتظر زرًا، استخدم Checkbox."},"speaker":"sara"},{"id":"S04","type":"tune","skill":"SK-P01-U02-06","part":"check","rules":["R19"],"value":{"en":"Skill check, input steppers (NN/g): use a stepper for numeric fields with a clear most-frequent value, set as the default. Most cleanings are 4 hours, from 2 to 8.","ar":"اختبار مهارة، الـ Stepper (NN/g): استخدمه للحقول الرقمية التي لها قيمة شائعة واضحة، واجعلها الافتراضية. وأغلب حجوزات التنظيف 4 ساعات، من 2 إلى 8."},"ref":{"url":"https://www.nngroup.com/articles/input-steppers/","quote":"Use steppers for numerical fields with a clear most frequently selected value."},"scenario":{"en":"The company told me cleanings last 2 to 8 hours, and most customers book 4.","ar":"أخبرتني الشركة أن التنظيف يستمرّ من 2 إلى 8 ساعات، وأن أغلب العملاء يحجزون 4."},"prompt":{"en":"Try each control for the hours. Which one should ship?","ar":"جرّب كل عنصر لعدد الساعات. أيّها يجب أن يُطلق؟"},"start":"select","options":[{"id":"stepper","text":{"en":"A stepper starting at 4","ar":"Stepper يبدأ من 4"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"text":"4"}]}},{"id":"select","text":{"en":"A dropdown from 2 to 8","ar":"قائمة منسدلة من 2 إلى 8"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"slider","text":{"en":"A slider from 2 to 8","ar":"Slider من 2 إلى 8"},"mock":{"width":300,"blocks":[{"kind":"slider","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"min":2,"max":8,"from":2,"to":5,"text":{"en":"Drag to choose","ar":"اسحب للاختيار"}}]}}],"answer":["stepper"],"misconceptions":[{"id":"MC-P01-023","when":["select"],"feedback":{"en":"Most people want 4, yet everyone opens a list to say so. Start at 4 and let the rest adjust with a tap.","ar":"أغلب الناس يريدون 4، ومع ذلك يفتح الجميع قائمة ليقولوا ذلك. ابدأ من 4 ودع الباقين يعدّلون بضغطة."}},{"id":"MC-P01-022","when":["slider"],"feedback":{"en":"Hours are exact whole numbers, and a slider makes her aim for one. A stepper lands on 4, 5 or 6 with no effort.","ar":"الساعات أرقام صحيحة دقيقة، والـ Slider يجعلها تصوّب نحو رقم. أما الـ Stepper فيصل إلى 4 أو 5 أو 6 بلا جهد."}}],"explain":{"en":"From Lesson 2: a small count with a usual value gets a stepper, starting at that value.","ar":"من الدرس 2: العدد الصغير ذو القيمة المعتادة يناسبه Stepper، يبدأ من تلك القيمة."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U02-05","part":"check","rules":["R19"],"value":{"en":"Skill check, date input (NN/g): disable and gray out options that aren't available. Only the company knows which days have a free team.","ar":"اختبار مهارة، إدخال التاريخ (NN/g): عطّل الخيارات غير المتاحة واجعلها رمادية. والشركة وحدها تعرف الأيام التي فيها فريق متاح."},"ref":{"url":"https://www.nngroup.com/articles/date-input/","quote":"Make the choices clear by disabling and graying out options that are not available or are illogical pairs."},"scenario":{"en":"Next week, the company has free teams only on Monday and Thursday.","ar":"في الأسبوع القادم، لدى الشركة فرق متاحة يومي الاثنين والخميس فقط."},"prompt":{"en":"Try each way of choosing the day. Which one should ship?","ar":"جرّب كل طريقة لاختيار اليوم. أيّها يجب أن تُطلق؟"},"start":"open","options":[{"id":"open","text":{"en":"Every day open; an error if no team is free","ar":"كل الأيام مفتوحة؛ ورسالة خطأ إذا لم يكن هناك فريق"},"mock":{"width":300,"blocks":[{"kind":"row","gap":"xs","blocks":[{"kind":"chip","text":{"en":"Sun 8","ar":"أحد 8"}},{"kind":"chip","text":{"en":"Mon 9","ar":"اثنين 9"}},{"kind":"chip","tone":"dark","text":{"en":"Tue 10","ar":"ثلاثاء 10"}},{"kind":"chip","text":{"en":"Wed 11","ar":"أربعاء 11"}},{"kind":"chip","text":{"en":"Thu 12","ar":"خميس 12"}}]},{"kind":"small","color":"red","text":{"en":"No team is free on this day. Try another.","ar":"لا يوجد فريق متاح في هذا اليوم. جرّب يومًا آخر."},"gap":"s"}]}},{"id":"field","text":{"en":"A date field she types into","ar":"حقل تاريخ تكتب فيه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Cleaning date","ar":"تاريخ التنظيف"},"text":{"en":"e.g. 10 November","ar":"مثلًا: 10 نوفمبر"}}]}},{"id":"blocked","text":{"en":"Only days with a free team can be picked","ar":"لا يمكن اختيار إلا الأيام التي فيها فريق متاح"},"mock":{"width":300,"blocks":[{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":{"en":"Sun 8","ar":"أحد 8"}},{"kind":"chip","text":{"en":"Mon 9","ar":"اثنين 9"}},{"kind":"chip","tone":"off","text":{"en":"Tue 10","ar":"ثلاثاء 10"}},{"kind":"chip","tone":"off","text":{"en":"Wed 11","ar":"أربعاء 11"}},{"kind":"chip","text":{"en":"Thu 12","ar":"خميس 12"}}]},{"kind":"small","text":{"en":"Grayed-out days are fully booked.","ar":"الأيام الرمادية محجوزة بالكامل."},"gap":"s"}]}}],"answer":["blocked"],"misconceptions":[{"id":"MC-P01-013","when":["open","field"],"feedback":{"en":"Laila can't know which days have a team, so she guesses until she stops getting errors. Show her before she picks.","ar":"لا تستطيع ليلى معرفة الأيام التي فيها فريق، فتخمّن حتى تتوقّف رسائل الخطأ. أرِها قبل أن تختار."}}],"explain":{"en":"From Lesson 2: when only the system knows the options, let people pick, and block what isn't possible, with a reason.","ar":"من الدرس 2: حين لا يعرف الخيارات إلا النظام، دع الناس يختارون، واحجب غير الممكن، مع ذكر السبب."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U02-08","part":"check","rules":["R19"],"value":{"en":"Skill check, dropdown lists (NN/g): people may not explore beyond the default. The area field preselects the most common area, so Laila may book in the wrong one.","ar":"اختبار مهارة، القوائم المنسدلة (NN/g): قد لا يستكشف الناس ما بعد الخيار الافتراضي. وحقل المنطقة يحدّد المنطقة الأكثر شيوعًا مسبقًا، فقد تحجز ليلى في المنطقة الخطأ."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"Users may not interact with the control to explore additional options beyond the default."},"scenario":{"en":"The company covers about 50 areas. Most bookings come from Nasr City, so the area field starts on Nasr City. Laila lives in Heliopolis.","ar":"تغطّي الشركة نحو 50 منطقة. وأغلب الحجوزات من مدينة نصر، فيبدأ حقل المنطقة بمدينة نصر. وليلى تعيش في مصر الجديدة."},"prompt":{"en":"Try each version of the area field. Which one should ship?","ar":"جرّب كل نسخة من حقل المنطقة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"select","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"}}]},"options":[{"id":"pin","text":{"en":"Type to search, with Nasr City pinned on top; nothing selected","ar":"اكتب للبحث، مع تثبيت مدينة نصر في الأعلى؛ دون تحديد شيء"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"text":{"en":"Type your area","ar":"اكتب منطقتك"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"small","text":{"en":"Most booked","ar":"الأكثر حجزًا"}},{"kind":"text","text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"xs"}]}]}},{"id":"keep","text":{"en":"Keep Nasr City preselected; it saves most people a step","ar":"أبقِ مدينة نصر محدّدة مسبقًا؛ فهي توفّر خطوة لأغلب الناس"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"}}]}},{"id":"radios","text":{"en":"Show all 50 areas as radio buttons","ar":"اعرض الـ 50 منطقة كلها كـ Radio buttons"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Area","ar":"المنطقة"}},{"kind":"radio","text":{"en":"Abbassia","ar":"العباسية"},"gap":"xs"},{"kind":"radio","text":{"en":"Agouza","ar":"العجوزة"},"gap":"xs"},{"kind":"radio","text":{"en":"Ain Shams","ar":"عين شمس"},"gap":"xs"},{"kind":"small","text":{"en":"… 47 more","ar":"… 47 منطقة أخرى"},"gap":"xs"}]}}],"answer":["pin"],"misconceptions":[{"id":"MC-P01-015","when":["keep"],"feedback":{"en":"A filled field looks answered. If Laila doesn't notice, the team goes to Nasr City. Pin the common area; don't choose it for her.","ar":"الحقل الممتلئ يبدو مُجابًا. وإذا لم تنتبه ليلى، يذهب الفريق إلى مدينة نصر. ثبّت المنطقة الشائعة؛ ولا تختَرها عنها."}},{"id":"MC-P01-016","when":["radios"],"feedback":{"en":"Nothing is preselected now, but fifty radio buttons take several screens of scrolling. A long list needs typing.","ar":"لا شيء محدّد مسبقًا الآن، لكن خمسين Radio button تحتاج تمرير عدة شاشات. والقائمة الطويلة تحتاج كتابة."}}],"explain":{"en":"From Lesson 3: let people type to search a long list, and pin common choices without preselecting them.","ar":"من الدرس 3: دع الناس يكتبون للبحث في القائمة الطويلة، وثبّت الخيارات الشائعة دون تحديدها مسبقًا."},"speaker":"sara"},{"id":"S07","type":"tune","skill":"SK-P01-U02-08","part":"check","rules":["R19"],"value":{"en":"Skill check, site search (NN/g): users often don't formulate perfect queries. \"Heliopolice\" is one letter off; suggest the match.","ar":"اختبار مهارة، البحث في الموقع (NN/g): كثيرًا ما لا يصوغ المستخدمون استعلامات مثالية. وما كتبته ليلى قريب جدًا؛ فاقترح المطابقة."},"ref":{"url":"https://www.nngroup.com/articles/internal-website-search/","quote":"Users often don’t formulate perfect queries."},"scenario":{"en":"In testing, Laila typed her area quickly: \"Heliopolice\".","ar":"في الاختبار، كتبت ليلى منطقتها بسرعة: «مصر الجديده»، بالهاء بدل التاء المربوطة."},"prompt":{"en":"Try each response. Which one should ship?","ar":"جرّب كل استجابة. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"none","text":{"en":"\"No results\"","ar":"«لا توجد نتائج»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Heliopolice","ar":"مصر الجديده"}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]}},{"id":"suggest","text":{"en":"Suggest the closest area","ar":"اقترح أقرب منطقة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Heliopolice","ar":"مصر الجديده"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","weight":"bold","text":{"en":"Heliopolis","ar":"مصر الجديدة"}}]}]}},{"id":"rule","text":{"en":"Say \"Check your spelling\"","ar":"قل «تحقّق من الإملاء»"},"mock":{"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Heliopolice","ar":"مصر الجديده"},"error":{"en":"Check your spelling.","ar":"تحقّق من الإملاء."}}]}}],"answer":["suggest"],"misconceptions":[{"id":"MC-P01-024","when":["none","rule"],"feedback":{"en":"The system can tell what she meant; it's one letter away. Make her fix nothing: suggest Heliopolis.","ar":"يستطيع النظام معرفة ما تقصده؛ فالفرق حرف واحد. لا تجعلها تصلح شيئًا: اقترح مصر الجديدة."}}],"explain":{"en":"From Lesson 3: forgiving search suggests the closest match instead of a dead end.","ar":"من الدرس 3: البحث المتسامح يقترح أقرب نتيجة بدل الطريق المسدود."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P01-U02-07","part":"check","rules":["R19"],"value":{"en":"Skill check, mobile input checklist (NN/g): what is the right keyboard for this field? A door code is a code: a number field would drop the leading zero of 0427.","ar":"اختبار مهارة، قائمة تحقّق حقول الهاتف (NN/g): ما لوحة المفاتيح المناسبة لهذا الحقل؟ ورمز الباب رمز: حقل الرقم سيحذف الصفر في أول 0427."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"What is the right keyboard for this field?"},"scenario":{"en":"The cleaning team needs the building's door code: 0427.","ar":"يحتاج فريق التنظيف رمز باب العمارة: 0427."},"prompt":{"en":"Try each field. Which one should ship?","ar":"جرّب كل حقل. أيّها يجب أن يُطلق؟"},"start":"number","options":[{"id":"number","text":{"en":"A number field","ar":"حقل رقم"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Door code","ar":"رمز الباب"},"filled":true,"text":"427"},{"kind":"small","color":"red","text":{"en":"Saved as 427: the leading 0 is gone","ar":"حُفظ هكذا: 427، واختفى الصفر في أوله"},"gap":"xs"}]}},{"id":"steps","text":{"en":"Four steppers, one per digit","ar":"أربعة Steppers، واحد لكل رقم"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Door code","ar":"رمز الباب"}},{"kind":"row","gap":"xs","blocks":[{"kind":"stepper","text":"0"},{"kind":"stepper","text":"0"}]}]}},{"id":"text","text":{"en":"A text field that opens the number pad","ar":"حقل نص يفتح لوحة الأرقام"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Door code","ar":"رمز الباب"},"filled":true,"text":"0427"},{"kind":"small","text":{"en":"Keyboard: 1 2 3 … 0","ar":"لوحة المفاتيح: 1 2 3 … 0"},"gap":"xs"}]}}],"answer":["text"],"misconceptions":[{"id":"MC-P01-021","when":["number"],"feedback":{"en":"A number field treats 0427 as the amount 427, and the team stands at the door with the wrong code. It's a code: text with the number pad.","ar":"حقل الرقم يعامل 0427 ككمية 427، فيقف الفريق أمام الباب برمز خاطئ. إنه رمز: نص مع لوحة الأرقام."}},{"id":"MC-P01-023","when":["steps"],"feedback":{"en":"Steppers are for small changes around a usual value. A code has no usual value; typing four digits is fastest.","ar":"الـ Stepper للتغييرات الصغيرة حول قيمة معتادة. والرمز ليس له قيمة معتادة؛ وكتابة أربعة أرقام هي الأسرع."}}],"explain":{"en":"From Lesson 2: IDs and codes are text made of digits. Use a text field that opens the number pad.","ar":"من الدرس 2: الأرقام التعريفية والرموز نص مكوّن من أرقام. استخدم حقل نص يفتح لوحة الأرقام."},"speaker":"sara"}]}$uxg$::jsonb)
